quests[10031] = { id = 10031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helping the Lost Find Their Way", description = "Many spirits of the draenei were corrupted by the explosion of Auchindoun.  Now they wander the wastes in torment.\n\n{name}, I beseech you to put them to rest.  Destroy the lost spirits and broken skeletons that haunt the Bone Wastes beyond Auchindoun's walls.\n\nWhat?  You think leaving them to wander in blind agony would be better?\n\nAfterward, return to Soolaveen at the Refugee Caravan and tell him of that which you have done.", sourceObjective = "Destroy 10 Lost Spirits and 10 Broken Skeletons, and then speak with Soolaveen at the Refugee Caravan in the Bone Wastes of Terokkar Forest.", progress = "{name}?  What brings you back to me?  Did you deliver the bones of the restless to Ramdor as I requested?", completion = "You have done that which needed doing and there is nothing to forgive.  Though it saddens me to hear that they were corrupted into a horrible undeath, through your actions you have put them to rest.\n\nThank you for setting them free, {name}.  You must accept a humble token of my regard for you and your selflessness.", sourceObjectiveStatus = "unverified-source-field" }
quests[10032] = { id = 10032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifacts from Tuurem", description = "Have you ever noticed the behavior of the Lost Ones in Tuurem? They wander the ruins, searching for surviving scraps of anything made by the draenei.\n\nTheir Broken masters know better. They've left their former lives and identities behind and become something completely different.\n\nI believe we can use the Lost Ones' compulsion to our benefit and gather old draenei relics from them. Why risk life and limb battling the Broken, when we can profit from picking our targets wisely?", sourceObjective = "Gather 6 Tuurem Artifacts from Tuurem Scavengers and Tuurem Hunters and bring them to Rakoria at Stonebreaker Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10033] = { id = 10033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Bonelashers Dead!", description = "A bounty is declared on the bonelashers of the Bone Wastes.  As known carriers of the plague, they are to be destroyed forthwith!\n\nWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.\n\nReport to Taela Everstride afterward to collect your reward.", sourceObjective = "Kill 20 Bonelashers and then report to Taela Everstride at the Allerian Stronghold in Terokkar Forest.", completion = "Yeah, I'm sure that you killed all of those bonelashers.  It's obvious since the captain asked for you to turn in proof on that wanted poster.\n\n<Taela gives you a sarcastic look.>\n\nI'll take your word for it.  I'm not certain who I angered to pull this duty, but thanks for your efforts on behalf of the Alliance.  Here's a little something for all of your trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[10034] = { id = 10034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Bonelashers Dead!", description = "The bonelashers of the Bone Wastes bit Mawg and made him sick.  Now he wants all of them destroyed!\n\nWhile they can be found throughout the wastes, they are known to congregate at Carrion Hill in the north.\n\nReturn to Mawg Grimshot after you've done the deed and he'll give you a good reward.", sourceObjective = "Kill 20 Bonelashers and then report to Mawg Grimshot at Stonebreaker Hold in Terokkar Forest.", progress = "Is that bonelasher blood on your hands that I smell?", completion = "You must have killed a lot of those bonelashers!  Good, I hate them!  Ever since I was bit by one of them, I keep having fainting spells.\n\nDo you realize how embarrassing that is?  Here, take this as thanks for exacting some revenge for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[10035] = { id = 10035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "There's a creature in the Bone Wastes so fearsome that only the dauntless dare to stalk him.\n\nI speak of Torgos, king of the bonelashers, who circles over Veil Rhaze on the western edge of the wastes.\n\nToo bad that there's an arakkoan scarecrow there, known as Torgos's Bane, which keeps him at bay.  I'd bet if you laid his mate Trachela's carcass at the foot of that scarecrow he'd come down anyway.  She can be found at Carrion Hill in the northern wastes.\n\nBring me one of Torgos's tail feathers.", sourceObjective = "Call down Torgos with Trachela's Carcass. Acquire a Tail Feather of Torgos and return it to Taela Everstride at the Allerian Stronghold in Terokkar Forest.", progress = "You have the feather?  Am I to reward you for your foolhardy bravery?", completion = "Color me impressed, {class}.  Torgos was one of the toughest creatures I know of this side of Nagrand.\n\nWell, I suppose that's good enough for something from the Allerian Stronghold treasury.  Take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[10036] = { id = 10036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgos!", description = "I want Torgos, king of the bonelashers, dead!\n\nNot long ago, while I was out hunting at Veil Rhaze on the western edge of the wastes, he fell upon me.\n\n<Mawg taps his eyepatch.>\n\nHe took my eye, and now I would have his life!  Bring me one of his tail feathers as proof and I'll give you a worthy reward.\n\nYou'll need his mate Trachela's carcass though to call him down as he's deathly afraid of the old arakkoan scarecrow known as Torgos's Bane.\n\nFind her at Carrion Hill in the northern wastes.", sourceObjective = "Call down Torgos with Trachela's Carcass. Acquire a Tail Feather of Torgos and return it to Mawg Grimshot at Stonebreaker Hold in Terokkar Forest.", progress = "Did you kill him?  Is Torgos dead?!\n\nYou have proof?", completion = "I thank you, {name}!  You have exacted my revenge, and as promised you will be rewarded!\n\nTake your pick of one of these and use it well!", sourceObjectiveStatus = "unverified-source-field" }
quests[10037] = { id = 10037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rather Be Fishin'", description = "Speaking of lakes, there's a lake with real good fishin' up to the northeast. I used to go up there with my friends, but my mom won't let me go anymore.\n\nShe says it's too dangerous, but I haven't seen anything up there but a few little spiders. Like spiders can do anything to you...\n\nMy favorites were always the eels that live up there. If you're going to be up by the lake, would you think about bringing back some of the eels? They're feisty but once you subdue 'em, you can bring 'em back no problem.", sourceObjective = "Bring 8 Pristine Shimmerscale Eels to Seth in Shattrath City.", progress = "<Seth tugs on your cloak.>\n\nDid you find the eels? Didja?", completion = "Thanks! I can't remember the last time I had eel!\n\nHow should I cook 'em?", sourceObjectiveStatus = "unverified-source-field" }
quests[10038] = { id = 10038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Private Weeks", description = "A report's just come in from one of our scouts near Grangol'var Village.  He says that a shadowy band has moved into the ruins there.\n\n{name}, I want you to speak with Private Weeks and see how you can assist him to figure out what this unknown group is up to.  Just head west past Stonebreaker Hold.  His last report puts his position near the north entrance to the village.", sourceObjective = "Speak with Private Weeks near the north entrance to Grangol'var Village in Terokkar Forest.", completion = "It's about time someone came out here.  I sent that report to the Allerian Stronghold over a week ago!\n\nBureaucracy!", sourceObjectiveStatus = "unverified-source-field" }
quests[10039] = { id = 10039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with Scout Neftis", description = "I am informed that one of our scouts near Grangol'var Village is currently observing a shadowy band that has recently moved in there.\n\n{name}, I want you to speak with Scout Neftis and see how you can assist her in figuring out what this unknown group is up to.\n\nJust head south out of here, and then due west, skirting the north of the Bone Wastes.  Her last report puts her position near the southern entrance to the village.", sourceObjective = "Speak with Scout Neftis near the south entrance to Grangol'var Village in Terokkar Forest.", completion = "It's about time someone came out here.  I sent that report to Stonebreaker Hold over a week ago!\n\nBlood elves and their bureaucracy!", sourceObjectiveStatus = "unverified-source-field" }
quests[10040] = { id = 10040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Are They?", description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.", sourceObjective = "While in disguise, speak with the Shadowy Initiate, the Shadowy Laborer and the Shadowy Advisor. Then return to Private Weeks at Grangol'var Village in Terokkar Forest.", progress = "You speak with all of them yet?  What did they have to say?", completion = "Good, you finally made it back!  Okay, what did you figure out?  Who are they?", sourceObjectiveStatus = "unverified-source-field" }
quests[10041] = { id = 10041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Are They?", description = "I don't know who they are, but I know they're hostile!\n\nI'm going to give you a disguise, and I want you to go in there and speak with three of them that I've observed as being 'chatty'. Talk with the initiate, the laborer, and the advisor.\n\nJust watch out; there're a few hunters in there who'll be able to see through your disguise and they look tough! And whatever you do, don't leave the village -- the disguise is kind of flimsy. If you lose your disguise, come back to me and I'll give you another.", sourceObjective = "While in disguise, speak with the Shadowy Initiate, the Shadowy Laborer and the Shadowy Advisor. Then return to Scout Neftis at Grangol'var Village in Terokkar Forest.", progress = "You speak with all of them yet?  What did they have to say?", completion = "Good, you finally made it back!  Okay, what did you figure out?  Who are they?", sourceObjectiveStatus = "unverified-source-field" }
quests[10042] = { id = 10042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Shadow Council!", description = "What!  Those guys are Shadow Council?!\n\n{name}, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.\n\nAfter you're done with that, report back to Lieutenant Gravelhammer at the Allerian Stronghold.\n\nGood luck, {class}!", sourceObjective = "Kill 10 Shadowy Executioners, 10 Shadowy Summoners and Shadowmaster Grieve, and then return to Lieutenant Gravelhammer at the Allerian Stronghold in Terokkar Forest.", completion = "That's dire news indeed!  Well, it would seem I made the right choice in sending you out there to help Weeks.  The last thing that we want is the Shadow Council establishing themselves right on our doorstep!\n\n{name}, in recognition of your efforts at Grangol'var Village, I hereby grant you the right to your pick of any of these fine rewards.", sourceObjectiveStatus = "unverified-source-field" }
quests[10043] = { id = 10043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Shadow Council!", description = "What!  Those guys are Shadow Council?!\n\n{name}, you have to go back in there and waste them!  I want you to take out their leader and as many of their executioners and summoners as you can.\n\nAfter you're done with that, report back to Advisor Faila at Stonebreaker Hold.\n\nGood luck, {class}!", sourceObjective = "Kill 10 Shadowy Executioners, 10 Shadowy Summoners and Shadowmaster Grieve, and then return to Advisor Faila at Stonebreaker Hold in Terokkar Forest.", completion = "That is unfortunate news!  But, of course, I made the right choice in sending you out there to help Neftis.  The last thing that we need is the Shadow Council establishing a strong point right on our doorstep!\n\n{name}, you've earned yourself something nice.  Go ahead, take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[10044] = { id = 10044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit With the Greatmother", description = "The Greatmother has asked that I seek you out and deliver a message. She wishes to speak with you at once.\n\nMy will has been sapped but make no mistake, {name}, if you anger the Greatmother, I will come down upon you with all the force that I can muster. She is in the main hall.\n\n<Garrosh points at the large building to the north.>\n\nListen to what she has to say and do as she tells you.", sourceObjective = "Speak to Greatmother Geyah and listen to what she has to tell you.", progress = "Please, sit down, dear.", completion = "We must first expand your mind so that you may commune with the ancestors.", sourceObjectiveStatus = "unverified-source-field" }
quests[10045] = { id = 10045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Material Components", description = "Mother Kashur wishes to speak with you, {name}. Before this becomes possible, you must collect the herbs required to create a potion that will expand your mind, allowing you to commune with the spirits.\n\nYou must gather Olemba root from Terokkar, marshberries from Zangarmarsh, Telaari fronds from Nagrand and dragonspine from the Blade's Edge mountains. I have written down instructions on this parchment as to the cultivation of these herbs. Return to me when you have gathered the materials.", sourceObjective = "Greatmother Geyah at Garadar in Nagrand has asked that you collect 1 Olemba Root, 1 Marshberry, 1 Telaari Frond and 1 Dragonspine.", progress = "Hello, dear.", completion = "You are very resourceful, {name}. Our greatest gatherers would have taken twice as long to collect the herbs.\n\n\n\nDo not be afraid.", sourceObjectiveStatus = "unverified-source-field" }
quests[10046] = { id = 10046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Dark Portal", description = "Two weeks ago, our scouts reported a heavily armed Alliance force under the command of Field Commander Romus departing Nethergarde Keep. With so many soldiers and supplies, along with such a distinguished commander, they can only have one goal: Outland.\n\nThe warchief sent an advance force through the portal, but if the Alliance believes there is a need for that many troops, perhaps we'd be wise to send our own reinforcements.\n\nJourney through the Dark Portal and report to Nazgrel at Thrallmar.", sourceObjective = "Travel through the Dark Portal and speak with Nazgrel at Thrallmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[10047] = { id = 10047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Glory", description = "The 'Path of Glory,' they called it. A road leading from the heart of their gruesome fortress to the Dark Portal, paved with the bones of my people.\n\nIt wasn't enough for them to hunt us down like animals, destroy our cities, and torture those who survived. No, they had to use our bones as paving stones, denying my brethren a proper burial under the Light.\n\nThose tortured souls still wander these lands, crying out for release. I ask you, {name}, help me in this undertaking.", sourceObjective = "Cleanse 8 Trampled Skeletons on the Path of Glory with Draenei Holy Water, then return to Warp-Scryer Kryv at Honor Hold.", progress = "The cries seem somehow... fainter than they were before. The Light grant it's more than wishful thinking.", completion = "You have my sincere thanks for your efforts, {name}. Though much remains to be done, it gladdens me to know we have helped some find their long-deserved rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[10050] = { id = 10050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unyielding Souls", description = "Near the end of our invasion, the Armory to the south fell under attack by the Horde's insidious Death Knights. Those vile shades cursed the Armory's defenders - and trapped their souls between the realms of the living and the dead.\n\nThose noble souls must be set free! I beg you, {name}, end my comrades' torment, for I have not the heart to slay them myself.", sourceObjective = "Honor Guard Wesilow wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south.", completion = "The Sons appreciate your efforts, even if few are willing to speak of the armory.", sourceObjectiveStatus = "unverified-source-field" }
quests[10051] = { id = 10051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Firewing Point!", description = "Thank goodness for you!\n\n{class}, I need you to help me escape.  I have information vital to the security of the Allerian Stronghold and probably all of Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!", sourceObjective = "Escort Isla Starmane to safety and then report to Captain Auric Sunchaser at the Allerian Stronghold in Terokkar Forest.", completion = "Isla Starmane just left, but she gave me a full rundown on what's going on out at Firewing Point.  It's understandable that she's quite distraught over what happened to the Cenarion Thicket.  Nasty blood elves!\n\nShe told me how you were instrumental in saving her so that we could get that information.  Allerian Stronghold is indebted to you for your service.\n\nPlease, accept this gift on behalf of us all.", sourceObjectiveStatus = "unverified-source-field" }
quests[10052] = { id = 10052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Firewing Point!", description = "Thank goodness for you!\n\n{class}, I need you to help me escape.  I have information vital to the security of Stonebreaker Hold and probably all of Outland!\n\nI came here from the Cenarion Expedition on a diplomatic mission, but as you can see, they weren't very friendly.  If you help me get to safety, I can assure you that you will be handsomely rewarded!", sourceObjective = "Escort Isla Starmane to safety and then report to Advisor Faila at Stonebreaker Hold in Terokkar Forest.", completion = "Isla Starmane just left, but she gave me a full rundown on what's going on out at Firewing Point.  It's understandable that she's quite distraught over what happened to the Cenarion Thicket.\n\nShe told me how you were instrumental in saving her so that we could get that information.  Stonebreaker Hold is indebted to you for your service.\n\nPlease, accept this gift on behalf of us all.", sourceObjectiveStatus = "unverified-source-field" }
quests[10055] = { id = 10055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste Not, Want Not", description = "Reinforcements are great, but I don't see 'em haulin' any wagons loaded with ingots or timber.\n\nTake a look around, friend. Trees are in short supply, and the mines are overrun with Legion scum.\n\nI'm in a bad way fer supplies, and I'm makin' what substitutions I can, but it's time to start reusing what we can.\n\nThe southern edge of the Path o' Glory is strewn with the ruins of siege machinery. Some pieces of 'em are still usable. Feeling up to a bit o' a salvage operation?", sourceObjective = "Bring 8 pieces of Salvaged Metal and 8 pieces of Salvaged Wood to Dumphry at Honor Hold.", progress = "Were you able to find any usable materials out there underneath all the dust, ash, and char?", completion = "This is in better condition than I thought it'd be. Sure, it's going to take some time to work off all the rust, the char, and the like, but I'll not complain.", sourceObjectiveStatus = "unverified-source-field" }
quests[10057] = { id = 10057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking to the Leadership", description = "The disturbances at Expedition Armory continue, despite your best efforts. No one truly knows everything that happened there, nor exactly what binds the spirits of the fallen soldiers to the ruins.\n\nPerhaps we've been approaching this the wrong way. I've always assumed that each of the ghosts had a tie to the ruins, but what if their ties were to their leaders?\n\nArch Mage Xintor and Lieutenant Commander Thalvos were particularly close to their men, so perhaps overcoming their ghosts will calm the rest.", sourceObjective = "Overcome the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos and return to Honor Guard Wesilow in the tower northwest of Honor Hold.", completion = "We can only hope that with the quieting of the ghosts of the officers, the spirits of the foot soldiers will follow. Thank you once again for your help, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10058] = { id = 10058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Gift", description = "<The priest's gaze slowly moves from his mug to you.>\n\nDon't you know better than to bother a man in his cups?\n\nOh, what's the use? I suppose newcomers are a good sign. What would Turalyon think?\n\nI remember the eve of our departure, when I gave Mysteries of the Light to him. During the campaign and the ensuing years, he never forgot to read his daily passage to the men.\n\nWhen he left us again, he gave the book back to me. Like a fool, I believed it safe in my quarters to the south of the armory.", sourceObjective = "Retrieve Mysteries of the Light and return it to Father Malgor Devidicus at Honor Hold.", progress = "I thought I asked you not to bother me. What is it?", completion = "Is that really it? It's hard to believe it survived the battle. Conditions in the ruins haven't been kind to the book, but still, I'm glad to have it.\n\nIt's the only token I have of Turalyon.\n\n<Father Devidicus seems to be fighting back tears.>\n\nWhen you fight beside someone for so many years, they become closer than even family.", sourceObjectiveStatus = "unverified-source-field" }
quests[10061] = { id = 10061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unyielding", description = "When the Bonechewer fel orcs attacked the Expedition Armory, the garrison there fell quickly.  The battle was bloody and fierce, and there were no survivors.\n\nAlthough the dead were buried, their spirits continue to haunt those ruins.  Of late, I have been receiving visions that these spirits may soon become a threat to Thrallmar.\n\nThere is only one course of action to take.  We must grant these spirits rest.  You must overcome them in battle.", sourceObjective = "Grelag wants you to defeat 12 Unyielding Footmen, 10 Unyielding Sorcerers, and 5 Unyielding Knights at the Expedition Armory to the south of Honor Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10063] = { id = 10063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explorers' League, Is That Something for Gnomes?", description = "Babysitting! Would you believe it?\n\nThey pulled me out of a promising dig and sent me along with Captain Odesyus' expedition to babysit that little gnome!\n\nI'd never heard o' a gnome wanting to become a prospector before, so I asked.\n\nSeems we are takin' gnomes now, and this particular one has a fascination with murlocs!\n\nWell, he's gone off and set up shop in an old turtle shell on the northern shore of the island. Go and have a look if you don't believe me!", sourceObjective = "Find Clopper Wizbang camped in an old turtle shell on the shore north of Blood Watch.", completion = "I thought so! That grumpy old dwarf was supposed to help me carry my equipment and gather data, but all he does is sit in that strange {race} town, drinking himself into a stupor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10064] = { id = 10064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talk to the Hand", description = "The Hand of Argus has established a forward base at Vindicator's Rest, but they are sorely outnumbered by both the blood elves and mutated wildlife. Without backup, their outpost is in danger of falling, and we'd have no way to keep an eye on events near the Vector Coil.\n\nReport to Scout Jorli at Vindicator's Rest to the northwest and offer her your assistance, {name}.", sourceObjective = "Report to Scout Jorli at Vindicator's Rest.", completion = "I was hoping Blood Watch would send reinforcements once they learned what we're up against.", sourceObjectiveStatus = "unverified-source-field" }
quests[10065] = { id = 10065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutting a Path", description = "During our mission to reconnoiter the Sunhawks and their portal, I sustained a serious wound. Scout Loryi has managed to staunch the bleeding and she's trying to figure out a way to evacuate me to Blood Watch.\n\nThe problem is that we'd have to abandon our position here in order to guarantee a safe return.\n\nAs soon as we leave this consecrated ground, we'll be set upon by ravagers. If you can clear some of the enraged ravagers, it might allow us to make the trip back safely.", sourceObjective = "Kill 10 Enraged Ravagers and return to Scout Jorli at Vindicator's Rest.", progress = "Have you managed to clear some of the ravagers in the area?", completion = "It looks a bit better out there, but I still wonder if I wouldn't be better off waiting for a medic here.", sourceObjectiveStatus = "unverified-source-field" }
quests[10066] = { id = 10066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, the Tangled Webs They Weave", description = "We don't dare abandon our post, or wander too far from Vindicator's Rest, {race}. The mutated creatures closest to the Vector Coil have been changed profoundly by energy leaking from the crystals.\n\nThe mutated tanglers appear to have gained a certain degree of sentience. They've learned to create, set, and conceal vicious traps that can ensnare even the most careful warrior.\n\nWe'll never be able to move against the Sunhawks if we're constantly forced to look underfoot. Attack the problem at its source, {name}.", sourceObjective = "Kill 8 Mutated Tanglers and report to Vindicator Corin at Vindicator's Rest.", progress = "Have you managed to clear any of the mutated tanglers?", completion = "Well done, {name}. It's going to be much easier to get reinforcements from Blood Watch, or launch strikes against the Sunhawks without having to worry about what the tanglers are up to.", sourceObjectiveStatus = "unverified-source-field" }
quests[10067] = { id = 10067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fouled Water Spirits", description = "Most of the creatures touched by the crystals' energy have been corrupted in the same ways: strange marks on their flesh, increased aggression, and small crystal shards in their bodies. However, the fouled water spirits north of here appear to be turning entirely to crystal.\n\nI've never seen anything react to the crystals this way before, when we explored the foul pool, they were particularly dangerous. We must get rid of them before the Sunhawks can exploit them as a new source of energy.", sourceObjective = "Kill 6 Fouled Water Spirits and return to Vindicator Corin at Vindicator's Rest.", progress = "Have you begun to clear the fouled water spirits?", completion = "Well done, {name}. It's important not to overlook any opportunity to deny the Sunhawks sustenance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10068] = { id = 10068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Nova", description = "As you begin to grow in power, your connection to the arcane will develop, granting you access to new spells.\n\nGo, develop your power, and then demonstrate what you learn for me.", sourceObjective = "Reach level 3 to learn Frost Nova. Locate a Training Dummy outside the Sunspire and practice using it 2 times.", progress = "Have you adequately practiced your new spell?", completion = "Ah good, a {class}.  I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[10069] = { id = 10069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ways of the Light", description = "It is time for your first lesson in the ways of the Light, {name}. As you fight more battles, it will bring you closer to the light, and you'll start to uncover new abilities.\n\nGo, get more experience, and learn a new ability. Return and demonstrate it for me, and we'll continue your training.", sourceObjective = "Reach level 3 to learn Seal of Command. Cast Seal of Command on yourself, then locate a Training Dummy outside the Sunspire and hit it.", progress = "Have you practiced using your new skills?", completion = "Ah good, a {class}.  I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[10070] = { id = 10070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady Shot", description = "And now, it is time for your first lesson.\n\nAs you become more skilled, you will begin to discover new techniques.\n\nGo out, get some more experience, and learn your first new ability. Once you do, go find a training dummy and practice your new skill.", sourceObjective = "Reach level 3 to learn Steady Shot. Locate a Training Dummy outside the Sunspire and practice using Steady Shot 5 times.", completion = "Ah good, a {class}.  I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[10071] = { id = 10071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evisceration", description = "As you grow in power, you'll start to figure out the tricks of the trade.\n\nOne of the first things you'll probably figure out is how to Eviscerate your enemy after landing some initial attacks.\n\nGet some experience, learn how to do it, and then find one of the training dummies outside and give it a try.", sourceObjective = "Reach level 3 to learn Eviscerate, then locate a Training Dummy outside the Sunspire and practice using Eviscerate 3 times.", progress = "Have you mastered your new skill?", completion = "Ah good, a {class}.  I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[10072] = { id = 10072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning the Word", description = "As you grow in skill, so will the array of powers that you can call upon.\n\nI'd like you to go, continue to become more experienced, and discover a new spell. Once you do, come back and demonstrate it for me.", sourceObjective = "Reach level 3 to learn Shadow Word: Pain. Practice casting it 5 times on nearby training dummies.", progress = "Have you aided the wounded outrunners?", completion = "Ah good, a {class}.  I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[10073] = { id = 10073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption", description = "By now, you've heard the rumors about our kind, the warlocks. Pay them no mind; they are uttered by those jealous of our fearsome powers.\n\nAs you become more experienced, you will uncover mysteries of controlling fel energies. \n\nGo, continue your journey until you uncover a new technique. I want you to practice using this new spell on the training dummies outside the Sunspire.", sourceObjective = "Reach level 3 to learn Corruption. Locate a Training Dummy outside the Sunspire and practice casting Corruption 5 times.", progress = "Have you mastered Immolate?", completion = "Ah good, a {class}.  I've been expecting you.\n\nThere are a few tasks that I have which you are particularly suited to.", sourceObjectiveStatus = "unverified-source-field" }
quests[10074] = { id = 10074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", description = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", sourceObjective = "Chief Researcher Amereldine at Halaa wants 10 Oshu'gun Crystal Powder Samples.", progress = "The crystalline powder from the mountain is infused within the earthen core of this region.", completion = "Wonderful, {name}. This will help us in our battle against the Alliance filth that have surfaced in the Outland.", sourceObjectiveStatus = "unverified-source-field" }
quests[10075] = { id = 10075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", progress = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", completion = "I am always accepting crystal powder contributions, {name}. You will be compensated for each set of samples that you recover." }
quests[10076] = { id = 10076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", description = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", sourceObjective = "Chief Researcher Kartos at Halaa wants 10 Oshu'gun Crystal Powder Samples.", progress = "The crystalline powder from the mountain is infused within the earthen core of this region.", completion = "Wonderful, {name}. This will help us in our battle against the Horde filth that have surfaced in the Outland.", sourceObjectiveStatus = "unverified-source-field" }
quests[10077] = { id = 10077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oshu'gun Crystal Powder", progress = "This base was the primary draenei research facility for the study of naaru crystals.\n\nWhat we have discovered is a veritable goldmine of research notes about the crystals from the \"diamond\" mountain, Oshu'gun. It would seem that everything in this region carries with it some residual powder of the Oshu'gun crystals. If you find any powder while adventuring in this region, return it to me and I shall reward you with a token of my appreciation which you may use to make purchases from the quartermaster.", completion = "I thank you for your contribution, {name}. Should you find more, you know where to bring them!" }
quests[10078] = { id = 10078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laying Waste to the Unwanted", description = "Now that we've gotten our salvage operation off the ground, it's time to begin the second phase of the plan.\n\nAcross the Path of Glory, the Horde still has their old blade throwers trained on us. Don't let their age fool you, {name}, they're still very dangerous. Much as we're working to reclaim what we can, we can't assume the Horde is going to dismantle their weaponry.\n\nTake this torch and burn the remaining siege equipment. I'll take no chances with Honor Hold's safety.", sourceObjective = "Use the Flaming Torch to burn the Horde Blade Throwers overlooking the Path of Glory. Then, bring the Flaming Torch to Dumphry in Honor Hold.", progress = "You seem to be in good spirits. Has burning Horde siege machinery put the spring back in your step?", completion = "That's the spirit!\n\nI'm glad we finally got some reinforcements, but I'm not so sure about their attitude toward the Horde. Where I come from, anyone with a weapon pointed at you is an enemy and needs to be dealt with like one!", sourceObjectiveStatus = "unverified-source-field" }
quests[10079] = { id = 10079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits!\n\nNot only did they run all my workers out of the tunnels, but they're pounding away in there night and day! To make things worse, now I've got Danath on me back! He says he's going to take away me ale ration if I don't get this taken care of soon!\n\nNone of the miners'll go in there, and the guards are busy drinking themselves silly.\n\nI'm begging you, {name}, help me here. Danath can take me dignity, but he'll never take me ale!", sourceObjective = "Kill 12 Gan'arg Sappers and return to Foreman Biggums.", progress = "Tell me the shaking's over and my boys can get back to work... please?", completion = "By Bronzebeard's bronze... beard, you've done it! You're a hero, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10081] = { id = 10081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Meet Mother Kashur", description = "Do not be alarmed by what you might see once the effect has taken hold! These spirits are all around us - always. The potion allows your mind to be able to understand and ultimately see the spirits. You will need to be under its influence if you are to speak with Mother Kashur.\n\nYou will find her a great ways to the southwest, at the Ancestral Grounds.", sourceObjective = "Greatmother Geyah wants you to speak with Mother Kashur.", completion = "The potion that you drank has no real effect. You can only see a spirit if they allow it. The potion is merely a symbol of your belief and dedication. It was a test and you passed...", sourceObjectiveStatus = "unverified-source-field" }
quests[10082] = { id = 10082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Agitated Ancestors", description = "Do you see them walking around us? The Ancestral Grounds are normally quiet and undisturbed.\n\nAs of late, the ancestral spirits have risen and are extremely agitated. Something is causing a great disturbance to the spirits. We must discover what that something could be, but first, we must put the immediate threat to rest.\n\nThese ghosts that you see walking about are not truly the ancestors but a representation of their state of being. You must destroy the agitated orc spirits. Do this and return to me.", sourceObjective = "Mother Kashur has asked that you put to rest 8 Agitated Orc Spirits.", progress = "You do not need a potion to see spirits, {name}.", completion = "It's no use. They continue to rise. There must be something more insidious underway.", sourceObjectiveStatus = "unverified-source-field" }
quests[10085] = { id = 10085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit With The Ancestors", description = "I need for you to journey to the villages of the ancestors, {name}. Seek each one out and see if the ancestors remain.\n\nVisit Sunspring Post to the north, visit the Laughing Skull Ruins far to the north against the mountains, visit Garadar to the northeast, and finally, visit the Bleeding Hollow Ruins on the borders of Nagrand and the Terokkar Forest, to the east.\n\nReturn to me once you have observed the ancestors in their homes.", sourceObjective = "Mother Kashur at the Ancestral Grounds in Nagrand has asked that you Visit Sunspring Post, Visit Laughing Skull Ruins, Visit Garadar and Visit Bleeding Hollow Ruins.", progress = "Move as the wind, {name}.", completion = "This is very troubling. You say that none of the ancestors were at their villages? That they were all moving south?", sourceObjectiveStatus = "unverified-source-field" }
quests[10086] = { id = 10086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Work... For the Horde!", description = "Would you believe it?  These orcs hired me to help them shore up damaged fortifications and build explosives.  What a dream job!  It's too bad we're so short on materials, but a clever goblin like myself learns how to make do!\n\nCan you help me?  I need salvaged wood and metal from the ruined battlements along the Path of Glory.  Go down there and salvage, and watch out for those red-skinned orcs!\n\nWhen you're done, come back for big rewards!", sourceObjective = "Bring 8 pieces of Salvaged Metal and 8 pieces of Salvaged Wood to Megzeg Nukklebust in Thrallmar.", progress = "So how did the salvage mission go?  Did you find anything useful?", completion = "This stuff is great!  A little bent and a little burnt, but I've never let low grade materials stop me from making precision high explosives.\n\nThanks, {name}.  You really have an eye for quality trash!", sourceObjectiveStatus = "unverified-source-field" }
quests[10087] = { id = 10087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn It Up... For the Horde!", description = "I'm a lucky, lucky goblin.  I get to make explosives and killing machines, knowing they'll be used immediately on important missions!\n\nSpeaking of missions, I just got one from Thrallmar command: burn the Alliance cannons on the far side of the Path of Glory... the ones pointing dangerously close to Horde fortifications.  Take this torch and make your way to each cannon.  Fire the torch and watch the sparks fly!", sourceObjective = "Use the Flaming Torch to burn the Eastern Alliance Cannon and the Western Alliance Cannon, and then return to Megzeg Nukklebust in Thrallmar.", progress = "I've been looking for the telltale signs of burning cannons -- smoke plumes, or the cries of burning fel orcs...\n\nAny luck on your mission?", completion = "I thought so!  I couldn't quite make out the destruction from here, but I can imagine how it must have looked.  Splendid!\n\nWell done, {name}.  Thrallmar command will be happy to hear of your success!", sourceObjectiveStatus = "unverified-source-field" }
quests[10091] = { id = 10091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Devices", description = "Gah!  They've been torturing me, trying to get me to tell them everything that I know.\n\nI failed - they fed the others to Hellmaw, and I was to be next.  But I told them nothing!\n\nThey're crazy!  They're hell-bent on summoning demonic forces that they have no way of controlling!\n\nThey're using special devices to make their soul shards, and their summoning, more powerful.  You must steal these devices!\n\nI would join you, but I must return to Shattrath City to report to the Lower City's spymistress.", sourceObjective = "Steal 5 Soul Devices and deliver them to Spymistress Mehlisah Highcrown at the Terrace of the Light in Shattrath City.", progress = "Yes?  What can I do for you, {class}?", completion = "To'gun was here earlier giving me his report.  He should have stayed with you to help!\n\nI sent him back out there to assist Grik'tha.  I think they make a cute couple.\n\nSo, these are the soul devices that the Shadow Council were using to enhance their summoning power?  They look dangerous to me - maybe the Scryers will know what to do with them?\n\nPlease, take one of these as a reward for crippling the Shadow Council's operation in the labyrinth.", sourceObjectiveStatus = "unverified-source-field" }
quests[10093] = { id = 10093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Temple of Telhamat", description = "Fortunately, the Path of Glory is not the only trace of my people in these lands. To the west, a few of our holy sites survive, although some have been overrun.\n\nWhile Velen prepared for the journey that would lead him to Azeroth, those of us who would remain behind sought to reestablish a presence at our holy places.\n\nIn the western part of the Hellfire Peninsula, you will find a small group of draenei at the Temple of Telhamat, led by Amaan the Wise. I am certain he'd be interested in meeting you.", sourceObjective = "Speak with Amaan the Wise at the Temple of Telhamat in western Hellfire Peninsula.", completion = "Ah, so you've met Seer Kryv. He is a wise and gifted man and any {race} he would name a friend is also a friend of mine.\n\nMake yourself comfortable and introduce yourself to the others who call the temple home.", sourceObjectiveStatus = "unverified-source-field" }
quests[10094] = { id = 10094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Blood", description = "It has been two years since the Shadow Council summoning that resulted in the explosion of this once-great mausoleum, and the formation of the Bone Wastes.\n\nNow they are at war with an unbelievably powerful force on the inside.\n\n{name}, you must make your way into the Shadow Labyrinth to determine what they are up against, and to see if it poses a threat to us.  Our spies speak of their use of a forbidden book of unholy summoning, known only as the Codex of Blood.\n\nSeek your answers within its pages.", sourceObjective = "Read from the Codex of Blood in the Shadow Labyrinth of Auchindoun.", completion = "Opening the magically-suspended tome, a sense of dread overwhelms you.\n\nSomething is most definitely wrong here!\n\nYou read on, but what you read seems unbelievable!", sourceObjectiveStatus = "unverified-source-field" }
quests[10095] = { id = 10095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Heart of the Labyrinth", description = "The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago!  It is what caused the explosion of Auchindoun, and the creation of the Bone Wastes beyond.\n\nKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!\n\nWith the grandmaster, and the rest of their leadership dead, you are Outland's last hope against this monstrosity!\n\n{name}, you know at the core of your being that you and your companions dare not fail!", sourceObjective = "Destroy Murmur and inform Spymistress Mehlisah Highcrown at the Terrace of Light in Shattrath City of the events that have transpired inside the Shadow Labyrinth.", completion = "Murmur almost broke free?!  They've had that thing contained in there for two years... I wonder what they did wrong to lose control over it after all this time?\n\n{name}, by putting that beast down you've likely saved all of us!  I cringe to think what would have happened to all of us here, and the rest of Outland, if that thing had somehow managed to break free!\n\nI'm glad you helped us to take matters into our own hands and deal with the Shadow Council threat at Auchindoun.  How can we ever reward you?", sourceObjectiveStatus = "unverified-source-field" }
quests[10096] = { id = 10096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Sporeloks", description = "Ikeyen's been telling me stories about what happened to him down in those caves and I think it's just awful!\n\nYou know, maybe we should do something to help out those poor sporeloks.  Ikeyen says that they live there in the Funggor Cavern, but that the marsh beasts have recently invaded.\n\nWhy don't you go down there and see if you can clear some of those marsh beasts out?  It's just to the southwest.", sourceObjective = "Slay 10 Marsh Dredgers and 10 Marsh Lurkers, and then return to Lauranna Thar'well at the Cenarion Refuge in Zangarmarsh.", progress = "What?  Back so soon?  How did it go?", completion = "Good!  Those marsh beasts have no right to invade the home of the sporeloks!\n\nIt would be better if these creatures would learn to live in harmony, but when that's not possible, we'll be here to take care of the situation!\n\nHere, please take one of these as thanks for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[10097] = { id = 10097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Against Brother", description = "The Sethekk departed Skettis with great fanfare when Auchindoun exploded. Surely it must've been an omen of our master's arrival.\n\nMy brother, Syth, was one of their leaders and told us we were obligated to go into the temple ruins and face our god.\n\nAfter we took up residence in the ruins, calling them the Sethekk Halls, I began to doubt my brother and his ally, Ikiss.\n\nIn time, Syth had me cast out of the Halls, but he refused to let me take our sister Lakka with me. Will you help me rescue her?", sourceObjective = "Kill Darkweaver Syth in the Sethekk halls, then free Lakka from captivity. Return to Isfar outside the Sethekk Halls when you've completed the rescue.", progress = "Did you find her, {name}? Was she still being held within the halls?", completion = "I can't thank you enough, {name}. Knowing that Lakka is free means I can cut the rest of my ties to the Sethekk.\n\nPart of me will never forgive myself for Syth's death, but it had to be done. When I reach Skettis, I will perform the death rites for him. Perhaps his spirit will find rest once it has atoned for leading our people astray.", sourceObjectiveStatus = "unverified-source-field" }
quests[10098] = { id = 10098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokk's Legacy", description = "My people honor an ancient hero named Terokk. Arakkoa hatchlings are regaled with stories of his deeds and descriptions of his beautiful plumage.\n\nHe dwelt among my people for hundreds of years, but mysteriously vanished one day, leaving only his mask, spear, and writings behind.\n\nThe relics are cherished by the arakkoa, but they were heartbroken when the Sethekk bore the objects away from Skettis at their departure.\n\nI have written down what little I know about their location within the halls.", sourceObjective = "Bring Terokk's Mask, Terokk's Quill, and the Saga of Terokk to Isfar outside the Sethekk Halls.", progress = "The relics of Terokk have been absent from Skettis for too long. Were you able to recover them from the Sethekk?", completion = "I may never truly be forgiven for my role in the crimes of the Sethekk, but perhaps by restoring the relics of Terokk to my people, I can begin to redeem myself.\n\nThank you for helping me in this, {name}. You have no idea of the magnitude of what you've done this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[10099] = { id = 10099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mastermind", description = "Those infernal gan'arg keep scurrying into the mine! For each one you kill, two or three more seem to take its place!\n\nThere's got to be someone down there in the deepest reaches of the mine directing the incursion. You seemed to do well against them last time, and Light knows you're the only one brave enough to venture back into the mine. Find out who's responsible for this disturbance and make him pay!", sourceObjective = "Locate and kill Z'kral in the mines beneath Honor Hold, then report back to Foreman Biggums.", progress = "I'm almost afraid to ask. Seeing you come out of the mine alive means one of two things: either you killed the monster, or you lost your nerve. Well, which is it?", completion = "I'm glad you managed to take care of, of... what did you say he called himself? Z'kral?\n\nFrom your description, it sounds more like an 'it' than a 'him' but all that matters is it's dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[10101] = { id = 10101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Spirits Speak", description = "Oshu'gun - the diamond mountain - was once sacred to my people. It was there that the clans would gather every year to celebrate the springtime festival. It was there that our shaman communed with the honored ancestors. It was the center of our culture - until the shadows overtook us. When the clans became a horde, the spirits of Oshu'gun fell silent. The ancestors turned their backs on us.\n\nYet something now draws them from their rest. Venture to Oshu'gun and discover what could trouble the spirits so.", sourceObjective = "Mother Kashur at the Ancestral Grounds in Nagrand has asked that you seek out the vision you had. Find K'ure in Oshu'gun.", completion = "<A gentle, melodic voice fills your mind.>\n\nI am K'ure of the naaru, {name}. You stand within the heart of my ancient vessel. \n\nOshu'gun, as the orcs named it, is the ship that first brought the draenei to this world.  Though we fell from the heavens and crashed here many hundreds of years ago, my weakened energies have remained trapped within this wreckage. Regrettably, I am the source of the orc spirits' pain.", sourceObjectiveStatus = "unverified-source-field" }
quests[10102] = { id = 10102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Secret Revealed", description = "As my energies bled away over the centuries, a void slowly grew in my place - devouring the souls of those nearby. Helplessly, I watched as generations of orc souls were drawn into the vortex. Recently, my enemies harnessed the vortex and used it to draw countless void minions into their Burning Legion.\n\nNow, the key to ending this cycle and freeing the orc spirits lies with another naaru - A'dal. I have sensed his essence within the ancient city of Shattrath in the Terokkar Forest.", sourceObjective = "Speak with A'dal in Shattrath City.", completion = "K'ure was wise to send you here. While we cannot assist you with the suffering of the orc ancestors, there is one that can.\n\nOne that is soon to be reborn of Light...", sourceObjectiveStatus = "unverified-source-field" }
quests[10103] = { id = 10103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Zurai", description = "With the arrival of Field Commander Romus and his forces, the Alliance and their draenei friends have grown bold. They're militarizing every old draenei ruin from here to Shattrath.\n\nIn response, the trolls have established a new outpost in the eastern part of Zangarmarsh, just south of the Dead Mire. Swamprat Post, they're calling it. I'm glad they have a sense of humor about living in a place like that, because I wouldn't relish it.\n\nThe post's commander has asked me to send anyone I can spare.", sourceObjective = "Report to Zurai at Swamprat Post in Zangarmarsh.", completion = "To be honest, I had expected more, but you'll have to do. Welcome to Swamprat Post.", sourceObjectiveStatus = "unverified-source-field" }
quests[10104] = { id = 10104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concerns About Tuurem", description = "The rumors from Tuurem are unsettling. Some say the town's ruins are overrun with crazed Broken and Lost Ones, while opportunistic artifact hunters steal draenei relics.\n\nIt's hard to know which are true and which aren't, but we have a responsibility to safeguard the ruins as best we can. Find Andarl at the Allerian Stronghold in Terokkar Forest. He is something of a student of magical relics. More than anyone else, he's likely to know what's going on there.", sourceObjective = "Speak with Andarl at the Allerian Stronghold in Terokkar Forest.", completion = "I'm flattered that your Broken friend considers me a scholar of his people's relics, but to be honest, I haven't had much chance to study them since my arrival here. It was certainly my intent, but when I arrived, I found that there were other matters that required my attention.", sourceObjectiveStatus = "unverified-source-field" }
quests[10105] = { id = 10105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News for Rakoria", description = "Now that Swamprat Post is complete, our control of the roads in and out of the marsh is much less tenuous. Our presence in Terokkar Forest is much less secure. Even so, at Stonebreaker Hold, Rakoria awaits word of our progress.\n\nShe's sharp and capable, {name}, but be careful around her. She's got a lot of goods she's eager to move along the roads, but don't assume she's got our best interests at heart. Rakoria goes where she believes there's profit to be found.", sourceObjective = "Speak with Rakoria at Stonebreaker Hold in Terokkar Forest.", completion = "I'd hoped his men would have the outpost complete sooner, but it's not costing him money. Still, it's progress.", sourceObjectiveStatus = "unverified-source-field" }
quests[10106] = { id = 10106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", progress = "{name}, return to me when you have aided in the capture of each of the forts!", completion = "Well done, {name}.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", sourceObjectiveStatus = "unverified-source-field" }
quests[10107] = { id = 10107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatic Measures", description = "Kilrath sends news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the southeast near the border of Terokkar. Good luck, {name}!\n\nBe warned, he is a blademaster...", sourceObjective = "Jorin Deadeye at Garadar in Nagrand has asked that you find and speak with Lantresor of the Blade in the Burning Blade Ruins.", progress = "Speak.", completion = "So what is your decision? Will it be war or will you lend your assistance?", sourceObjectiveStatus = "unverified-source-field" }
quests[10108] = { id = 10108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatic Measures", description = "The huntress's agents send news of the Boulderfist leader: He is an orc! An ancient orc that passed through the Dark Portal in the time of our fathers and has since returned to his homeland. I wish for you to track down this orc and try to convince him to pull back the Boulderfist ogres. He resides on an upper platform in the Burning Blade Ruins to the east. Good luck, {name}!\n\nBe warned, he is a blademaster...", sourceObjective = "Mo'mor the Breaker at Telaar in Nagrand has asked that you find and speak with Lantresor of the Blade in the Burning Blade Ruins.", progress = "Speak.", completion = "So what is your decision? Will it be war or will you lend your assistance?", sourceObjectiveStatus = "unverified-source-field" }
quests[10109] = { id = 10109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Must Have Them!", description = "Do you see them?? By Gazlowe's horrific halitosis, I will have those eggs! Say, you look like you might be of some use.\n\nI'll tell you what, {race}; if you gather a few items for me to make my Jump-a-tron 4000 functional, I'll give you a key that will let you operate the machine as well! What can you do with a Jump-a-tron 4000 you say? What can't you do is more like it...\n\nI'll need air elemental gas from the air elementals of Nagrand. They're all over the place so don't ask me where to find 'em!", sourceObjective = "Wazat across from Clan Watch in southern Nagrand wants you to bring him 3 Air Elemental Gases.", progress = "Got gas?", completion = "Excellent! Now just a few adjustments and this thing will be as good as new. Oh yes, your key! Here you go.\n\nBy the way, the Jump-a-tron still has a few kinks that I need to work out. Um, just be careful.", sourceObjectiveStatus = "unverified-source-field" }
quests[10110] = { id = 10110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", progress = "Return to me after you have helped capture each fort!", completion = "Nice work, {name}.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", sourceObjectiveStatus = "unverified-source-field" }
quests[10111] = { id = 10111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me The Egg!", description = "Now that you've been initiated, I want you to get me that egg! Use the Jump-a-tron and try to hit the nest dead center. But be careful! Bodily injury or serious permanent damage may occur from a bad jump.", sourceObjective = "Wazat in Nagrand wants you to use the Jump-a-tron 4000 to get to the nest in the nearby tree and steal the Mysterious Egg.", progress = "Did I mention my love for eggs?", completion = "Well, it's no egg... Hey! I love chicken too! I'll just chomp right through this ginourmous talon! Thanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[10112] = { id = 10112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Favor", description = "Hmmm?  A box you say?  Or was it several?  Do you know what material the box was constructed from?\n\nAnd what was the name of this merchant?  Empoor?  Are you certain that he's one of the Broken?  I don't do much business with their kind.\n\nPerhaps my memory would be jogged if you were to do me a favor?\n\nThe Skithian arakkoa - primitive casters that they are - recently stole a huge shipment of my more exotic goods.  I want it all back!\n\nYou can find Veil Skith just to the south of Shattrath City.", sourceObjective = "Retrieve 5 of Lathrai's Stolen Goods. Return them to Wind Trader Lathrai near the World's End Tavern in the Lower City section of Shattrath City.", progress = "Hmm, is my memory improving?", completion = "Yes, indeed, I do believe that it's all getting clearer now.\n\nAnd I think that your diligence in this matter deserves more than just the information that you seek.", sourceObjectiveStatus = "unverified-source-field" }
quests[10113] = { id = 10113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nesingwary Safari", description = "\"Go out and find us some supplies,\" he said. I was nearly killed about 15 times before I found this place! These Broken might not be the most hospitable bunch but at least they're not trying to tear my skin from my bones.\n\nAnyway, I'm not going back. My days of huntin' big game are over. If you end up heading northeast towards Zangarmarsh and run into the Nesingwary Safari, let them know that \"Shotgun\" quit. \n\nHey, maybe you can take my place! Good luck, stranger.", sourceObjective = "\"Shotgun\" Jones wants you to speak with Hemet Nesingwary at the Nesingwary Safari on the outskirts of northeast Nagrand.", completion = "I suppose we'll have to find a replacement water boy. Say, you look like a powerful {class}. Interested in a job? Or did you come for the hunt?", sourceObjectiveStatus = "unverified-source-field" }
quests[10114] = { id = 10114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nesingwary Safari", description = "These orcs have never seen a tauren before - if you can believe such a thing. If it weren't for Captain Kroghan, they would have probably been serving me for their next meal right about now.\n\nBut where are my manners? I am Ohlorn Farstrider, hunter extraordinaire! I am part of the Nesingwary expedition that came up here from Azeroth in search of big game. If you are interested in the hunt, perhaps you should visit my crew at the Nesingwary Safari, due east of here near the border of Zangarmarsh.", sourceObjective = "Ohlorn Farstrider wants you to speak with Shado 'Fitz' Farstrider at the Nesingwary Safari in Nagrand.", completion = "I am relieved to hear that he is safe. Have you come to join the hunt?", sourceObjectiveStatus = "unverified-source-field" }
quests[10115] = { id = 10115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggerfen Deviance", description = "The Kurenai and the draenei don't always see eye to eye, particularly on the issue of the Lost Ones. We are content to help the Lost Ones who seek us out, but we won't pursue them. Some draenei are intent on 'redeeming' them all.\n\nHowever, there are times when even the Lost Ones go too far, such as the Daggerfen. In their village to the west, they dabble in poisons and deceit, arts that come unnaturally to us.\n\nWe must put an end to this before the vile Daggerfen can extend their influence.", sourceObjective = "Slay 3 Daggerfen Assassins and 15 Daggerfen Muckdwellers.", progress = "Have you seen what the Daggerfen have done? Now you understand why we must isolate them from the other Lost Ones.", completion = "You have done well, {name}. The Daggerfen are beyond redemption by anyone's standards, but I'm not certain that the draenei would've acted with the proper speed in this situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10116] = { id = 10116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Chieftain Mummaki", description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against the Orebor Harborage.\n\nThe chieftain and his band of assassins are responsible for the deaths of numerous Kurenai and draenei and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid the Daggerfen Village area to the west of the Orebor Harborage.\n\nTo claim the bounty, present proof of the chieftain's demise to Ikuti.", sourceObjective = "Bring Chieftain Mummaki's Totem to Ikuti at the Orebor Harborage.", progress = "So you wish to claim the bounty on Chieftain Mummaki?", completion = "Remarkable! There have been others who tried to claim the bounty, but they never returned. It's not hard to figure out what happened to them.\n\nI'm relieved that we'll no longer be troubled by Mummaki and his degenerates.", sourceObjectiveStatus = "unverified-source-field" }
quests[10117] = { id = 10117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Chieftain Mummaki", description = "Wanted: Chieftain Mummaki - leader of the foul and degenerate Lost One tribe of the Daggerfen, for his brutal attacks against Zabra'jin and its inhabitants.\n\nThe chieftain and his band of assassins are responsible for the deaths of numerous scouts and messengers and should only be approached by seasoned combatants.\n\nTravelers are advised to avoid the Daggerfen Village area to the northwest of Zabra'jin.\n\nTo claim the bounty, present proof of the chieftain's demise to Shadow Hunter Denjai.", sourceObjective = "Bring Chieftain Mummaki's Totem to Shadow Hunter Denjai.", progress = "So you wish to claim the bounty on Chieftain Mummaki?", completion = "You have my thanks, {name}. I was beginning to think that I was going to have to take a substantial part of the garrison up there and deal with Mummaki myself. Of course, there's no telling what might have happened to Zabra'jin then.", sourceObjectiveStatus = "unverified-source-field" }
quests[10118] = { id = 10118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to the Daggerfen", description = "Of all the Lost One tribes in Zangarmarsh, the Daggerfen are the most cunning and most aggressive. They are highly organized and make no secret of the fact that they desire control over the other Lost Ones in the marsh.\n\nTheir attacks have already taken quite a toll on my scouts and messengers. I cannot afford to lose any more men.\n\nIf we don't act soon, they'll have complete control over the roads and Zabra'jin will effectively be surrounded.", sourceObjective = "Slay 3 Daggerfen Assassins and 15 Daggerfen Muckdwellers and return to Shadow Hunter Denjai at Zabra'jin.", completion = "I think you've managed to send a fairly strong message to them. Perhaps now, the rest of my men won't be so afraid to take the fight to the Daggerfen. Or, if they are, they'll find themselves ashamed by their lack of bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[10119] = { id = 10119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Dark Portal", description = "For 20 years the Dark Portal has remained a silent monument - a eulogy to a time long since forgotten.\n\n<Relthorn looks around.>\n\nI never thought to see this day, yet here we stand, looking into the abyss.\n\nOn the other side of this gate we are locked in a savage war - a war that we cannot win without support. You must go through the Dark Portal and help our troops, {class}.\n\nReport to Commander Duron at once. He awaits you in Outland...", sourceObjective = "Travel through the Dark Portal and find Commander Duron. He awaits your arrival on the other side - in the Outland.", completion = "Welcome to Outland, {name} -- welcome to the nightmare! Though the initial Expeditionary Force made it through unscathed, the Legion is attempting to retake the Dark Portal and prevent any of our reinforcements from coming through.\n\nAs much as I'd like your aid here, our troops and the Horde soldiers are able to fend off the Legion platoons that are attempting to take control of this platform.\n\nWe need you where your talents can best be utilized.", sourceObjectiveStatus = "unverified-source-field" }
quests[10120] = { id = 10120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arrival in Outland", description = "Aided by the Alliance, my forces will hold the line here, but I need you to deliver my report to General Krakork in Thrallmar. With his help, we'll be able to drive these demons back into the abyss that spawned them! Speak to Vlagga Freyfeather who stands on the platform behind us. She'll speed you on your way.", sourceObjective = "Lieutenant General Orion at the Dark Portal in Hellfire Peninsula wants you to bring Orion's Report to Vlagga Freyfeather.", progress = "I saw you speaking with Orion - it must be important business...", completion = "So you're Orion's new messenger? I pray you fare better than the last one he sent, {class}.  With the Legion pressing in, you'd never make it to Thrallmar on foot. Say the word, and my faithful wyvern will deliver you there safely.", sourceObjectiveStatus = "unverified-source-field" }
quests[10121] = { id = 10121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eradicate the Burning Legion", description = "Though this land is full of strange new enemies, the Burning Legion is still the greatest threat to our Expedition. One of my most trusted warriors, Sergeant Shatterskull, has been studying the Legion's tactics - trying to discern the demons' true purpose in this land. Seek him out at the supply caravan just outside the southern wall.\n\nAnd {name} - be wary of the Legion. Their evil cannot be underestimated.", sourceObjective = "Speak with Sergeant Shatterskull at the Supply Caravan just outside of Thrallmar, to the east.", completion = "No doubt you saw the Legion's warriors dotting the landscape on your flight from the Dark Portal. Though we defeated them at the Battle of Mount Hyjal some five years past, the cursed demons just keep coming back for more. If it's a challenge they crave, then the Horde will answer in kind!\n\nWe orcs have more than just a score to settle with the Legion. What about you, {name}? Shall I tell you of our enemy?", sourceObjectiveStatus = "unverified-source-field" }
quests[10122] = { id = 10122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Citadel's Reach", description = "Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable scouts, Private Imarion, to track their movements, preparations and numbers, but he hasn't returned to report his findings.\n\nImarion was to focus his efforts on the northernmost camp along the Southern Rampart, near where it joined the Citadel. Find him, {name}. Without his information, we're sitting ducks.", sourceObjective = "Search the northernmost camp along the Southern Rampart for any trace of Private Imarion.", sourceObjectiveStatus = "unverified-source-field" }
quests[10123] = { id = 10123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felspark Ravine", description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.\n\nThey have stationed dreadlords in Felspark Ravine, east of here. They are responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.", sourceObjective = "Sergeant Shatterskull at the Supply Caravan east of Thrallmar in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.", progress = "Thrallmar is safe so long as the arcanist and his bloodmages remain at the front.", completion = "Outstanding work, soldier. The frequency of the attacks is sure to lessen - at least until they bring forth more dreadlords.\n\nNow for the bad news: I've got your new orders...", sourceObjectiveStatus = "unverified-source-field" }
quests[10124] = { id = 10124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Base: Reaver's Fall", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Forward Commander To'arch.\n\nNow move out!", sourceObjective = "Report to Forward Commander To'arch at Reaver's Fall.", completion = "So you're the one responsible for clearing out Felspark, eh?  That's good to hear - we need soldiers like you who can take these fiends head on!", sourceObjectiveStatus = "unverified-source-field" }
quests[10125] = { id = 10125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Disrupt Communications", description = "Directly east of here is the Legion Front. The front acts as a mobile command station for the Burning Legion. Jutting out of the ground you'll see Legion antennas. The Legion uses these to communicate with their forge camps throughout Outland. They also serve as wards to scramble Legion transmissions, making magical surveillance impossible.\n\nI want you to take these explosives and use them to obliterate the antennas. Get all of them, {name}. They run south to north on the border of the Legion Front.", sourceObjective = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you use To'arch's Explosives and destroy Legion Antenna: Spite, Legion Antenna: Rage, Legion Antenna: Hate, Legion Antenna: Fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[10127] = { id = 10127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Sever the Tie", description = "It would be a dereliction of duty if I did not order you to take out the demons that inhabit the Legion Front, just east of this base.\n\nBoth sides of the front are set up in the same manner: Fel handlers roam between Legion encampments, which are in turn guarded by wrathguards. A shivan subjugator oversees the entire operation. Kill 'em all and let Kazzak sort 'em out.\n\nAnd watch out for patrolling fel reavers. I know you're tough but those things will make short work of you.", sourceObjective = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula wants you to kill 4 Fel Handlers, 8 Wrathguards, and Subjugator Shi'aziv.", sourceObjectiveStatus = "unverified-source-field" }
quests[10129] = { id = 10129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Gateways Murketh and Shaadraz", description = "We've identified the two main transporters that the Burning Legion are using to bring in reinforcements: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into oblivion!\n\nHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Brack -- he'll put you on a wyvern.", sourceObjective = "Speak with Wing Commander Brack, bomb Gateway Murketh and Gateway Shaadraz and then return to Forward Commander To'arch at Reaver's Fall.", progress = "If you missed during your first pass, take another...", completion = "That will set them back weeks! Fantastic work, {name}. The Legion never expected such heavy resistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10130] = { id = 10130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Flank", description = "In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.\n\nAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Honor Hold.\n\nWith the hold's garrison concentrating on its eastern walls, an attack from the west would be devastating. Honor Hold can only hope to hold out if the western forces are kept out of the battle.", sourceObjective = "Kill 10 Shattered Hand Guards, 10 Shattered Hand Berserkers, and 5 Shattered Hand Acolytes, then report to Lieutenant Amadi at Honor Hold's western guard tower.", sourceObjectiveStatus = "unverified-source-field" }
quests[10132] = { id = 10132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Colossal Menace", description = "You see that huge red crystal to the north?  It fell from the sky not long ago, causing a massive earthquake.\n\nWhen we came out here to investigate the disturbance, we found all of these colossi wandering about that weren't previously here.\n\nThere's definitely something strange about that crystal and the energies that it's emanating, but I don't have time for that.  Those mountain giants are my immediate concern.\n\nI want you to head up to Fallen Sky Ridge and deal with them.", sourceObjective = "Slay 5 Raging Colossi and then return to Tola'thion at the Cenarion Post in Hellfire Peninsula.", completion = "Good work.\n\nIf you ask me, all that we have to do is kill enough of those colossi, and then we won't have to worry any longer about the ridge or that strange crystal in the middle of it.\n\nHere, take one of these as a gift from the Cenarion Expedition.", sourceObjectiveStatus = "unverified-source-field" }
quests[10134] = { id = 10134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crimson Crystal Clue", description = "As the colossus falls under the weight of your attacks, you notice for the first time that it was holding a red crystal fragment.\n\nWhile it was small and unnoticeable in the mountain giant's hand, it's a fairly hefty piece for you to carry around.  It also suspiciously looks like it's a piece of the giant crystal in the middle of the ridge.\n\nIt's most definitely a clue as to the strangeness that is occurring here, and you're sure that the druids at the Cenarion Post to the south will want to see it.", sourceObjective = "Deliver the Crimson Crystal Shard to Tola'thion at the Cenarion Post in Hellfire Peninsula.", progress = "That's a big crystal you have there.  Did you get that while you were up at the ridge killing colossi?\n\nLet me take a look at it.", completion = "Hmph.  Just looks like a big lump of unrefined crystal to me.\n\nAdmittedly, I can feel a sickly, evil aura emanating off of it, but that's not exactly in my line of work.  I'm just here to put an end to the mountain giant menace.", sourceObjectiveStatus = "unverified-source-field" }
quests[10136] = { id = 10136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruel's Intentions", description = "Magister Bloodhawk finally deciphered the Legion missive you found earlier. It turned out to be attack plans sent by one of Highlord Kazzak's lieutenants - Arazzius the Cruel. Apparently, Arazzius commands the Legion ground forces in Hellfire. The time has come to terminate his command, {name}. Terminate with extreme prejudice. \n\nHead west to the Pools of Aggonar and put an end to this so-called 'Legion lord'. Today, the Horde reclaims Hellfire Peninsula. Let the Legion be damned.", sourceObjective = "Kill Arazzius the Cruel, then return to Nazgrel in Thrallmar.", progress = "Destiny calls, {name}. Arazzius the Cruel has eluded justice long enough. Let his death be a message to all those who would oppose the Horde.  You are next.", completion = "For generations to come, they will sing songs of this day, {name} - songs of your valor. I wish Thrall had been here to celebrate this victory with us. The Legion is undone - and Hellfire now belongs to the Horde once again! There may yet be hope for this ravaged world - and our peoples' place within it. \n\nLok'tar ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[10140] = { id = 10140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Honor Hold", description = "When you're ready, I'll arrange a flight straight to Honor Hold.\n\nFrom there, speak with Marshal Isildor and give him Duron's report.  He'll be happy to see another recruit from the homelands, and I'm sure the information in that report is important stuff!", sourceObjective = "Take a flight to Honor Hold and deliver Duron's Report to Marshal Isildor.", progress = "Thank the Light you made it here safely. Honor Hold needs all the seasoned warriors it can muster.", completion = "Our expedition to this forsaken, wreck of a world has almost ground to a halt, {name}. We encountered more resistance than we bargained for.\n\nAs if facing the Burning Legion again wasn't bad enough - there are horrors in this land unlike anything we've ever encountered.", sourceObjectiveStatus = "unverified-source-field" }
quests[10141] = { id = 10141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legion Reborn", description = "While the Burning Legion invaded Azeroth, they were also at work here, in Outland.  We have tracked their movements over the years, but this latest activity, {class} - well, this is beyond anything we've seen.\n\nSeek out Sergeant Altumus near the eastern supply caravan. She has been monitoring the invaders and may have insights into their purpose.\n\nBe swift - and take care, {name} - the Burning Legion is not to be underestimated.", sourceObjective = "Speak with Sergeant Altumus at the East Supply Caravan just outside of Honor Hold, to the east.", completion = "Force Commander Danath may have misunderstood my request for reinforcements. You look capable, but... I asked for a full sized battalion!\n\nYou see, we have a bit of a demon problem...", sourceObjectiveStatus = "unverified-source-field" }
quests[10142] = { id = 10142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Anguish", description = "Doom Lord Kazzak commands the Burning Legion in Outland. While we can't get to Kazzak - yet - we can and must get to his lieutenants that command Legion troops from the ground.\n\nThey have stationed dreadlords at the Path of Anguish, east of here. They are the ones responsible for these infernal storms that rain down upon our heads. To take them and their minions out would be a great set back to the Burning Legion.", sourceObjective = "Sergeant Altumus at the East Supply Caravan east of Honor Hold in Hellfire Peninsula wants you to kill 4 Flamewaker Imps, 6 Infernal Warbringers and 1 Dreadcaller.", progress = "Honor Hold is safe so long as the archers guard our skies.", completion = "Outstanding work, soldier. The frequency of the attacks is sure to lessen - at least until they bring forth new dreadlords.\n\nNow for the bad news: I've got your new orders...", sourceObjectiveStatus = "unverified-source-field" }
quests[10143] = { id = 10143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition Point", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Rohamus's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 400 paces, across the Valley of Bones, until you run into a destroyed fel reaver. You'll see Expedition Point where a Legion base used to stand. Once there, you are to report to Forward Commander Kingston.\n\nNow move out!", sourceObjective = "Report to Forward Commander Kingston at Expedition Point.", completion = "Glad to meet you, soldier.\n\nEnough chatting... now listen up -- I have a vital mission for you and I want you to succeed... and survive!", sourceObjectiveStatus = "unverified-source-field" }
quests[10144] = { id = 10144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt Their Reinforcements", description = "You'll find the Legion front to our northeast, and spaced along it are portals used to gather reinforcements from throughout Outland. We, {name}, are going to destroy those portals!\n\nTake this primer.  Designed in Area 52, it uses the demons' own power as an explosive device!  Defeat Legion forces around Portals Grimh and Kaalez to gather demonic rune stones, use the primer to detonate the stones inside the portals... then watch the fireworks!!\n\nGo, {name}, and return to me when your mission is complete.", sourceObjective = "Defeat enemies around Portal Grimh and Portal Kaalez to gather Demonic Rune Stones.\n\nUse Kingston's Primer inside Portal Grimh and Portal Kaalez.\n\nReturn to Forward Commander Kingston with the remaining explosives.", progress = "I wish I could be there to watch the fire display.  Those explosives pack a big punch!", completion = "Well done, {name}.  Disabling those portals will stem the flow of Legion reinforcements for a long time!\n\nBut we can't rest yet...", sourceObjectiveStatus = "unverified-source-field" }
quests[10146] = { id = 10146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Murketh and Shaadraz Gateways", description = "Just west of the Dark Portal are two huge transporters: Gateway Murketh and Gateway Shaadraz.\n\nIf you look east up the Path of Glory, you'll see them on either side of the road.  I want you to bomb them both into rubble!\n\nHere are the bombs you'll use, specially designed by a goblin in Area 52.  Now, speak with Wing Commander Dabir'ee -- he'll put you on a gryphon and send you on your way.", sourceObjective = "Speak with Wing Commander Dabir'ee, bomb Gateway Murketh and Gateway Shaadraz and then return to Forward Commander Kingston at Expedition Point.", progress = "This is a vital mission, {name}.  It's one I would not trust to just anyone.", completion = "That will slow them down, there's no denying it! I think you just put me in an uncharacteristically good mood, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10150] = { id = 10150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Citadel's Reach", description = "Each day, Hellfire Citadel opens its gates, and more fel orcs pour out and into the camps they've established along the ramparts south of the fortress.\n\nI dispatched one of my most capable trackers, Scout Makha, to track their movements, preparations and numbers, but she hasn't returned to report her findings.\n\nMakha was to focus her efforts on the northernmost camp along the Northern Rampart, near where it ends in the rocks. Find her, {name}. Without her information, we're sitting ducks.", sourceObjective = "Search the northernmost camp along the Northern Rampart for any trace of Scout Makha.", sourceObjectiveStatus = "unverified-source-field" }
quests[10152] = { id = 10152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Flank", description = "In addition to other instructions, the orders tell the remaining fel orcs to prepare their equipment and rations for a coming attack.\n\nAccording to the plans, Warboss Nekrogg's forces are to form the western flank of a pincer attack on Thrallmar.\n\nWith the town's garrison concentrating on its eastern walls, an attack from the west would be devastating. Thrallmar can only hope to hold out if the western forces are kept out of the battle.", sourceObjective = "Kill 10 Shattered Hand Guards, 10 Shattered Hand Berserkers, and 5 Shattered Hand Acolytes, then report to Stone Guard Ambelan at Spinebreaker Post near Zeth'Gor.", sourceObjectiveStatus = "unverified-source-field" }
quests[10159] = { id = 10159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Thornfang Hill Clear!", description = "We've been fighting an ongoing battle to keep the pass through Thornfang Hill to the west clear of ravagers.  It would be bad if we were to become completely cut off from the refuge in Zangarmarsh.\n\nWe don't want to displace the creatures, but there seems to be little choice as their attacks on travelers through the area have become more aggressive.\n\nClear some of the ravagers out of there if you can.", sourceObjective = "Kill 8 Thornfang Ravagers and 8 Thornfang Venomspitters, and then return to Mahuram Stouthoof at the Cenarion Post in Hellfire Peninsula.", progress = "How fares your attempt to clear Thornfang Hill?", completion = "With the ravagers cleared, travelers to and from the Cenarion Refuge in Zangarmarsh should have an easier time of it.\n\nThe Cenarion Expedition is indebted to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10160] = { id = 10160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know your Enemy", description = "Rumors have surfaced that some new breed of orc is on the rise. Larger, meaner - more cunning than the brutes we're familiar with.  If these rumors are true then our forces, already stretched, may be taxed beyond their limit.\n\nI have entrusted my lieutenant, Amadi, with investigating this matter. If you would help us in this dark hour, seek her out. She is stationed at the broken tower just west of the Hold.\n\nAnd {name} - be careful out there. You're heading into a dangerous new world.", sourceObjective = "Speak with Lieutenant Amadi at the old guard tower just west of Honor Hold.", completion = "<Lieutenant Amadi nods.>\n\nGood, we need all the help we can get. The increasing fel orc presence around the Southern Rampart concerns me. I sent out a scout to investigate, but he hasn't yet returned.", sourceObjectiveStatus = "unverified-source-field" }
quests[10161] = { id = 10161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Case of Emergency...", description = "In the event of an emergency, it's always the pilot's job to keep a level head, especially when the only orders your co-pilot follows come from his stomach.\n\nThe good news is that we won't need to wait days for replacement parts to be imported. The bad news is that the \"spare\" parts got scattered from here to the Valley of Bones to the east.\n\nThe other bad news? The spare parts aren't so spare. They, uh, fell off during our rapid descent. Could you help me collect enough to get us off the ground again?", sourceObjective = "Collect 30 pieces of Zeppelin Debris and bring them to \"Screaming\" Screed Luckheed at the Zeppelin Crash.", progress = "Did you find enough of the parts? If not, I might have to use that frying pan Legassi keeps waving around. Then, I'd have to rename the zeppelin the \"Flying Skillet.\"", completion = "Some of this is in pretty bad shape, but there should be enough to work with here. With some creative engineering, I'm confident I can make it work!", sourceObjectiveStatus = "unverified-source-field" }
quests[10162] = { id = 10162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Abyssal Shelf", description = "Now that you've got your wings, perhaps you'd be interested in running another bombing mission?\n\nThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a wyvern and destroy the whole damned thing!\n\nHere are your bombs - now, talk to Wing Commander Brack when you're ready for takeoff.", sourceObjective = "Forward Commander To'arch at Reaver's Fall in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", progress = "Show them that not even the skies are safe!", completion = "You fly as if you've been doing this your entire life, {name}. Outstanding performance out there! Not even a scratch on the wyvern destroyers!", sourceObjectiveStatus = "unverified-source-field" }
quests[10163] = { id = 10163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: The Abyssal Shelf", description = "Now that you've got your wings, perhaps you'd be interested in running another bombing mission?\n\nThis time we've isolated the Legion's main production area, behind the forge camps to the north. I need you to get on a gryphon and destroy the whole damned thing!\n\nHere are your bombs - now, talk to Gryphoneer Windbellow when you're ready for takeoff.", sourceObjective = "Wing Commander Gryphongar at Shatter Point in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons, 5 Mo'arg Overseers and 5 Fel Cannons.", progress = "Show them that not even the skies are safe!", completion = "You fly as if you've been doing this your entire life, {name}. Outstanding performance out there! Not even a scratch on the gryphon destroyers!", sourceObjectiveStatus = "unverified-source-field" }
quests[10164] = { id = 10164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Will Be Alright", description = "You've had quite an adventure, {name}. And before you've even set foot inside of the Auchenai Crypts.\n\nI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.\n\nWhat I ask is simple. Enter the Auchenai Crypts and destroy Exarch Maladaar so that the spirits trapped inside can finally rest in peace.", sourceObjective = "Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and destroy Exarch Maladaar.", progress = "Save the spirits, {name}.", completion = "You've done it, {name}! The spirits are freed!\n\nAlthough I am without a material manifestation, I am still able to reward you with items from the spirit world. Use them with caution as such items are often volatile and can cause great harm to their user.", sourceObjectiveStatus = "unverified-source-field" }
quests[10165] = { id = 10165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercutting the Competition", description = "That Shaffar is a shrewd one - I'll give him that... He's managed to keep the Consortium out while he safely pillages this crypt for all it's worth. I have no faith in these imbeciles actually breaking through Shaffar's defenses so I'll make you a deal, {race}.\n\nEnter the Mana-Tombs and kill Nexus-Prince Shaffar. Bring me back his body wrap as proof of this deed and I'll reward you handsomely.", sourceObjective = "Nexus-Prince Haramad located outside of the Mana-Tombs wants you to kill Nexus-Prince Shaffar and bring Shaffar's Wrappings back to him.", progress = "I don't like to \"share.\"", completion = "Another competitor goes under... You do good work for a flesh beast, {race}. If you are ever in Netherstorm, look me up. I make my home at the Stormspire.", sourceObjectiveStatus = "unverified-source-field" }
quests[10166] = { id = 10166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitebark's Memory", description = "This pendant brings back memories of a different time.  A better time.\n\nUnfortunately, memories are the last thing I need right now.\n\nI want you to bury this by the runestone in the Scorched Grove.  It was there that I first met the treant elder.  Put my old friend's memory to rest.", sourceObjective = "Larianna Riverwind wants you to place Old Whitebark's Pendant by the runestone at the Scorched Grove.", progress = "You've returned, {name}.  Haven't you done enough?", completion = "I no longer belong to this world and must admit defeat.  The land has forever changed and nothing will ever be the same.\n\nLeave the pendant here with me, {name}.  Maybe one day, long after the elves are gone, a new tree will grow on this very spot - amongst a burnt forest and the husks of dead treants.", sourceObjectiveStatus = "unverified-source-field" }
quests[10167] = { id = 10167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoun...", description = "Deep within the Auchenai Crypts is a tomb: A tomb unlike any that exists on this shattered realm. It was from this tomb, the first tomb, that the vast mausoleum of Auchindoun was born.\n\nYou must venture to the Auchenai Crypts of Auchindoun and find this tomb. Slay the guardian of the crypt to release the captive spirit within. The spirit holds the key...", sourceObjective = "Travel to the Auchenai Crypts in the Bone Wastes of Terokkar Forest and slay Exarch Maladaar to free the spirit of D'ore.", completion = "The memory is vivid, {name}. My energies were wholly drained from the crash. I was only a dim speck of void energies when the Prophet Velen and his draenei compatriots lifted my remains and brought them here. After much ceremony, my diminished form was laid to rest within this sarcophagus. I have been regenerating for nearly a thousand years. The cycle is almost complete...", sourceObjectiveStatus = "unverified-source-field" }
quests[10168] = { id = 10168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Soul Sees", description = "For several centuries, the spirits of Auchindoun coalesced into my darkened essence. Many of the catastrophes that befell this crypt were a direct result of my weakened state.\n\nRegrettably, there is nothing that can be done to stop this cycle. It is a facet of the naaru condition - without the void, the Light cannot exist.\n\nYour only recourse is to destroy the ancient spirits of Nagrand before they transform into creatures of the void. Use the soul mirrors found throughout this crypt to free them...", sourceObjective = "Locate a Soul Mirror somewhere in the Auchenai Crypts and use it to call forth a Darkened Spirit from Ancient Orc Ancestors in Nagrand. Destroy 15 Darkened Spirits so that the ancestors may rest in peace.\n\nReturn to Mother Kashur at the Ancestral Grounds when this task is complete.", progress = "<Mother Kashur is visibly upset.>\n\nThese naaru are wise beyond all manner of life on this world.", completion = "You have completed a long and dangerous journey, risking life and limb to ensure the safety of the Mag'har and the serenity of our ancestors. For this I am thankful beyond what words could convey.", sourceObjectiveStatus = "unverified-source-field" }
quests[10169] = { id = 10169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Losing Gracefully", description = "The Aldor have gained the favor of the Sha'tar today.  As if that should come as any sort of surprise!\n\nWatch them showing off their fancy footwork a few feet away from A'dal.  Could they possibly put any more effort into sucking up to the naaru?\n\nHarbinger Haronem's marksman regiment is so dedicated, it even brings its own cooking pot to avoid taking long breaks for lunch.  This cannot go without retribution, {name}.\n\nI want you to pour this vial into their meal.  The results should be... comical.", sourceObjective = "Magister Falris in Shattrath wants you to take the Vial of Sedative Serum to the Terrace of Light and pour it into Haronem's Regiment Cooking Pot.", sourceObjectiveStatus = "unverified-source-field" }
quests[10170] = { id = 10170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Greatmother", description = "Return to Greatmother Geyah at Garadar with news of your victory, {name}. This will surely lift the spirits of the Mag'har. Perhaps even the young Hellscream will be lifted from his malaise.", sourceObjective = "Return to Garadar and speak to Greatmother Geyah.", completion = "I want you to personally deliver this news to Garrosh.", sourceObjectiveStatus = "unverified-source-field" }
quests[10171] = { id = 10171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Inconsolable Chieftain", description = "You have done so much for the Mag'har, {name}. Your accomplishments are known to all, including Garrosh. Go to him now and tell him of your latest victory. Tell him that you do what you do for him and his people. Surely he will be lifted by your words.", sourceObjective = "Greatmother Geyah at Garadar has asked that you speak with Garrosh.", completion = "Everyone is proud. Proud that our people will live to see another winter. But beyond that? What is there?\n\nMaybe you should lead this clan, {name}. Maybe then I will be allowed to die when the Greatmother passes. Allowed to finally erase the shame of my family name. I long for such peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[10172] = { id = 10172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There Is No Hope", description = "You are an honorable {race}, {name}. You have done much for the Mag'har. No one could ever deny your service to my people. Alas, the time of the Mag'har is at an end. You have shown me, more than anything, that I am unfit to lead these people. My cursed blood runs too deep. I will not... I cannot become the second Hellscream to damn the orcs.\n\nPlease, {name}, return to the Greatmother and tell her what I have told you. I am too ashamed to see her... to look into her eyes.", sourceObjective = "Speak to Greatmother Geyah and tell her what Garrosh told you.", progress = "<Greatmother Geyah is lying down.>", completion = "<Tears stream down Greatmother Geyah's face.>\n\nSeek out your warchief. Tell him that I await him here...", sourceObjectiveStatus = "unverified-source-field" }
quests[10173] = { id = 10173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Archmage's Staff", description = "Allow me to introduce myself, {class}.\n\nI am Ravandwyr, apprentice to the Archmage Vargoth.\n\nMy master is... indisposed, shall we say. I am here on a matter of great importance.\n\nThe Arklon Ruins southeast of the city are a hotbed of Burning Legion activity. Their purpose in the ruins concerns neither me nor my master, but their leader, Ekkorash, possesses the archmage's staff.\n\nThis conjuring powder will allow you to draw the demon out of hiding. Sprinkle it on the brazier at the center of the ruins.", sourceObjective = "Retrieve Archmage Vargoth's Staff from Ekkorash the Inquisitor and bring it to Ravandwyr in Area 52. To bring Ekkorash out of hiding, sprinkle the Conjuring Powder on the brazier in the center of the ruins.", progress = "I will not rest until Archmage Vargoth's staff is restored to him. Were you able to wrest it from the demon's grasp?", completion = "Ah, so you managed to recover the staff. Impressive, {name}. Perhaps you are the one I've been looking for.\n\nOh yes, your reward...\n\n\n\nNo doubt you had higher expectations, but that too will come with time. For now, consider opportunity the true reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10174] = { id = 10174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curse of the Violet Tower", description = "Now, you will be able to use the archmage's staff to contact him.\n\nHe resides in the Violet Tower, on an 'island' to the southeast. The tower is both sanctuary and prison to him, cursed as it is. Kirin Tor can neither enter nor leave, keeping me apart from my master.\n\nThe staff's magic can penetrate the tower's defenses, but only if invoked by one outside the Kirin Tor.\n\nTake the archmage's staff and use it to conjure his image. Tell him what has happened and that I have not completely failed him.", sourceObjective = "Use Archmage Vargoth's Staff to make contact with Archmage Vargoth.\n\nIf you lose Archmage Vargoth's Staff, speak to Ravandwyr at Area 52 to receive a replacement.\n\nProvided item:", completion = "<Archmage Vargoth's image examines you as you convey Ravandwyr's message.>\n\nRavandwyr has everything a master can expect of his apprentice. When I gave him the staff and told him to flee, I hoped that he would use it to find help and free me once Kael'thas's forces withdrew from the tower. Since then, I have learned a great deal about the nature of the curse.\n\nIt can be broken, {name}, but it will require your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[10175] = { id = 10175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrall, Son of Durotan", description = "Return to your world, {name}. Go to my grandchild and tell him that his blood is here - on this shattered world.\n\nTell him that his father's legacy lives on.\n\nTell him everything...", sourceObjective = "Venture to Orgrimmar and deliver Geyah's message to Thrall.", completion = "<Thrall's voice takes on the hollow essence of a storm cloud.>\n\nI... I have a grandmother? She lives?", sourceObjectiveStatus = "unverified-source-field" }
quests[10176] = { id = 10176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ar'kelos the Guardian", description = "Now that you've gathered all the items I'll need to break Kael'thas's curse, one thing remains to be done. When Kael'thas sealed the tower, he placed an arcane golem, known as Ar'kelos, at the bottom of the tower.\n\nYou must defeat Ar'kelos in order allow me to work magic within the tower again.\n\nWhen you enter the Violet Tower, the curse will begin to affect you.\n\nOnce you have defeated Ar'kelos, ascend the tower and assist me in making preparations for the ritual.", sourceObjective = "Enter the Violet Tower at the center of Kirin'Var Village and defeat Ar'kelos, then speak with Archmage Vargoth.", progress = "At last, we meet.", completion = "You have done well, {name}. Destroying the dampening field will make it much easier for me to prepare the magic that will lift the tower's curse at last.", sourceObjectiveStatus = "unverified-source-field" }
quests[10177] = { id = 10177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Auchindoun", description = "I have spies within Auchindoun and they have been sending me disturbing reports.  That place has been nothing but trouble ever since it exploded a couple of years ago.\n\nSomething in there has gone horribly wrong - again - and the Shadow Council is now on a war footing.  Though the reports were lacking on details, their preparations appear to be directed inward.\n\nYou must make your way to the entrance of the Shadow Labyrinth.  My field commander, Mahfuun, will fill you in on what needs to be done.", sourceObjective = "Report to Field Commander Mahfuun at the entrance to the Shadow Labyrinth at Auchindoun in Terokkar Forest.", completion = "It's about time that you arrived.\n\nMehlisah said that she would be sending help days ago.  And we've been fighting in here longer than that!", sourceObjectiveStatus = "unverified-source-field" }
quests[10178] = { id = 10178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Spy To'gun", description = "To'gun, the fool!  We're barely holding off the attacks here, and he goes back in to get more information and try to save the other spies!\n\nI don't know whether to love him or kill him!\n\nThe Shadow Council must have used magic to ferret us out, because all of our spies had to get out of there in a hurry.  Most of us didn't make it.\n\nPlease, if you're brave enough to enter the Shadow Labyrinth, will you keep an eye peeled for To'gun?  It's been a while, and I fear the worst.", sourceObjective = "Locate Spy To'gun in the Shadow Labyrinth of Auchindoun.", completion = "What?  Grik'tha sent you in here after me?\n\nI don't know whether to be touched or call her a fool!\n\nDo you think you could help me get out of this cage?  It's a bit cramped.", sourceObjectiveStatus = "unverified-source-field" }
quests[10179] = { id = 10179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Custodian of Kirin'Var", description = "When it became clear that our expedition was trapped in Outland with no way to return to Azeroth, the Kirin Tor contingent traveled to the Plains of Farahlon and built Kirin'Var village. I left the administration of the town in the hands of Custodian Dieworth, but when Kael'thas and his forces sealed me in the Violet Tower, I lost contact with the custodian.\n\nSearch for him in Kirin'Var Village and help him in any way you can, {name}. I'm certain he's got his hands full in the aftermath of the attack.", sourceObjective = "Speak with Custodian Dierworth at Kirin'Var Village in Netherstorm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10180] = { id = 10180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Stay Away", description = "I tried to persuade Isfar to remain here, in the safety of Shattrath, but he would have none of it. Instead, he's decided to venture out to Auchindoun again on his own.\n\nHe was lucky enough to escape the Sethekk Halls once, but if they discover him, there won't be a second time.\n\nI admire his desire to free his sister, but he's not going to be able to do it without help.\n\nFind Isfar and have a word with him, {name}. If you can't persuade him to come back, perhaps you could help him rescue Lakka?", sourceObjective = "Speak with Isfar, who can be found just inside the Sethekk Halls in Auchindoun.", completion = "I should've suspected he would send you after me. He tried to talk me out of returning to the Sethekk Halls, but I couldn't live with myself if I allowed Lakka to die in there.", sourceObjectiveStatus = "unverified-source-field" }
quests[10182] = { id = 10182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle-Mage Dathric", description = "The sword is of exceptional quality, finely crafted and perfectly balanced for a battle-mage. The seal of the Kirin Tor and the name \"Dathric\" are engraved into the weapon's pommel.\n\nTurning the weapon over in your hands, you notice a sense of wrongness radiating from the metal, as if the item is torn between two worlds. Could this be the item anchoring Battle-Mage Dathric's spirit to this world?\n\nPerhaps returning it to its proper place can break the bond, freeing Dathric's spirit to rest at last.", sourceObjective = "Locate Battle-Mage Dathric's quarters in Wizard's Row and return the blade to his weapon rack. Then, speak with Custodian Dieworth at Kirin'Var Village.", progress = "What have you found, {name}?", completion = "You've done well, {name}. I can no longer sense any restlessness in Dathric's spirit. I would give much for the opportunity to speak to him one more time, but it is enough that he is finally at rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[10183] = { id = 10183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off To Area 52", description = "I'm out here studying the nether - the ethereal currents and all that.  This is an ideal spot away from the lights and hubbub of town.  Isn't this bridge great?  If I could just keep this junk working.\n\nHey, you know, if you're looking for work there's plenty at Area 52!  It's just up the path and take a right at the fork in the road.\n\nWhy don't you deliver my latest research notes to Rocket-Chief Fuselage?  I'm sure that he'd have plenty for you to do, what with the X-52 rocket ship, and all!", sourceObjective = "Deliver the Netherologist's Notes to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "Busy, busy.  No time to waste!  There's a rocket ship to be built!\n\nWhat do you want?", completion = "Oh, Coppernickels finally decided to report his findings, did he?  Lazy scientists!\n\nWhat's this?\n\n<The chief riffles through the notations a few times, clearly with a look of disbelief.>\n\nHe says here that the violent nether-energies flowing through the Netherstorm are going to rip everything to shreds in only a few months.\n\nThat's inconvenient - now we'll have to move up the time-table on building the rocket ship!", sourceObjectiveStatus = "unverified-source-field" }
quests[10184] = { id = 10184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malevolent Remnants", description = "Most of the spirits in the village are little more than pale remnants of Kirin Tor mages. They retain no knowledge of their former selves and wander the ruins in blind anger.\n\nIt wasn't always like this, though. In the immediate aftermath of the attack, the spirits were restless, but not spiteful. With the passage of time they have only grown more aggressive. I dare not venture into the southern part of the village, for they will not spare even me. Quiet them and let us hope it will purge their anger.", sourceObjective = "Custodian Dieworth at Kirin'Var Village wants you to defeat 20 Severed Spirits in Kirin'Var's Town Square.", progress = "It pains me to know there is so little to be done for our comrades.", completion = "<Custodian Dieworth shakes his head gently.>\n\nIt is not what they deserved, but it is the best we can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10185] = { id = 10185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fate Worse Than Death", description = "After the blood elves leveled Kirin'Var Village, they started the construction of a large building to the northwest. Without the expertise of the archmage, we can't say for certain what's going on there.\n\nOne thing is clear, though. The blood elf activities have unleashed a tide of ravenous mana elementals on the village. They seem drawn to the ruins of Wizard Row, wreaking further destruction. We cannot permit this to continue.", sourceObjective = "Kill 10 Mageslayers and 10 Mana Seekers and return to Custodian Dieworth at Kirin'Var Village.", progress = "Have you managed to clear out some of the mana creatures from the village ruins?", completion = "<The custodian looks dismayed.>\n\nI can already see the next wave coming over the horizon. Culling them will work for the time being, but more permanent measures are needed.", sourceObjectiveStatus = "unverified-source-field" }
quests[10186] = { id = 10186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're Hired!", description = "Let me be the first to welcome you aboard, Junior Technician 3rd Grade {name}!\n\nWe're building my masterpiece out here - the X-52 Nether-Rocket!\n\nBut first we need to get all of the parts and fuel for it.  That's where you come in.\n\nTo start, I need crystals - LOTS of crystals - for the rocket's Etherlithium Engine Matrix.  The draenei had crystals coming out of their ears!\n\nSo head north to the Ruins of Enkaat and get them for me!  Nevermind all of the draenei ghosts.", sourceObjective = "Collect 10 Etherlithium Matrix Crystals and return them to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "Does it look like the X-52 Nether-Rocket is ready for liftoff?  Am I cruising the Twisting Nether in the comfort of my command chair?  Exploiting strange new worlds?  Seeking out new technology and business opportunities?  Boldly going where no goblin has gone before?\n\nNo!\n\nSo, I hope you have those crystals that I sent you after.", completion = "Gah!  Those look rough.  Maybe we can use them in the tertiary engine manifold chamber?\n\nStill, a good job Junior Technician 3rd Grade!  You'll make 2nd Grade in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[10187] = { id = 10187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Message for the Archmage", description = "Although things are grim here, it heartened us quite a bit to hear from you that the archmage has not forgotten the village's plight.\n\n<The custodian glances up at the tower.>\n\nIt's ridiculous, isn't it? Sometimes it seems all that separates us is a wall of mere stone. The wall of magic is easy enough to forget.\n\nIf you would be so kind, ascend the tower and let Archmage Vargoth know that we are making progress with the village and will soon have a plan to ward off the mana creatures.", sourceObjective = "Speak to Archmage Vargoth at the top of the Violet Tower in Netherstorm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10188] = { id = 10188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sigil of Krasus", description = "Before we departed Azeroth all those years ago, the Kirin Tor entrusted our expedition with a powerful artifact, the Sigil of Krasus. It was a great boon to us in our battle against the orcs and it could play a key role in helping me break the enchantment that imprisons me.\n\nHowever, when Kael'thas divested me of my possessions, he gave the sigil to Spellbinder Maryana, who remained behind with the garrison. If he truly realized what he had in his possession, he wouldn't have given it away so easily.", sourceObjective = "Retrieve the Sigil of Krasus from Spellbinder Maryana at Manaforge Coruu, northwest of the Violet Tower.", progress = "If I am to be free of the tower's curse, I must have the sigil.", completion = "Ah, it is as magnificent as I remembered. Can you not feel the power radiating from it?\n\nOf course, there is much more to be done, but you have my deepest thanks for restoring the sigil to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[10189] = { id = 10189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manaforge B'naar", description = "You may have noticed one of Kael's manaforges on your way here.  You know, the large purple buildings sucking energy from the sky?\n\nWe were sent here by the Sha'tar to investigate them.  You can help our information gathering efforts by obtaining a personnel roster.  Giving us an idea of who's there and what they do will prove to be invaluable information.\n\nWe believe Captain Arathyn, leading a ballista team just outside of Manaforge B'naar, is in possession of one such roster.  Obtain it for us.", sourceObjective = "Spymaster Thalodien at Area 52 wants you to go to the outskirts of Manaforge B'naar and retrieve the B'naar Personnel Roster from Captain Arathyn.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Did you obtain the items I asked of you, {name}?", completion = "Excellent!  With this roster we can make more educated decisions when targeting Kael's followers at the manaforges.\n\nIt's too bad, I was beginning to take a liking to killing his lackeys indiscriminately.", sourceObjectiveStatus = "unverified-source-field" }
quests[10190] = { id = 10190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recharging the Batteries", description = "I have the very important task of collecting the machinery inside these ruins, but I'm having a problem keeping all of my bots charged up.\n\nThe phase hunters - those wyrm-looking things - have lots of energy!  You can find them all over the edges of this island, floating in from the nether.\n\nFill the battery on this recharging blaster by using it on a phase hunter when they're very weak, and then finish it off to soak up the last of its energy.", sourceObjective = "Use the Battery Recharging Blaster on enough Phase Hunters to get the Battery Recharge Level to 10. Then return it to Bot-Specialist Alley at the Ruins of Enkaat in the Netherstorm.", progress = "Have you recharged the battery in that blaster yet?", completion = "Hey, watch where you're pointing that thing!  You've got it set to 'Kill'!!!\n\nIt looks like you've recharged the battery, and then some.  This'll help immensely to keep these guys going.", sourceObjectiveStatus = "unverified-source-field" }
quests[10191] = { id = 10191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mark V is Alive!", description = "Greetings, {race}.  I am charged up and fully functional.\n\nThere are fragile draenei machines in these ruins, which I must retrieve.  I am equipped with delicate servos in my wrist actuators, and the latest in combustion-pneumatic bump soakers.  Handling them with care will not be an issue.\n\nHowever, the ghosts that haunt these ruins will likely attack, so I will need you and your friends along for protection.", sourceObjective = "Escort the Maxx A. Million Mk. V through the Ruins of Enkaat and back out to safety. Then speak with Bot-Specialist Alley just outside the Ruins of Enkaat in the Netherstorm.", progress = "Back so soon?\n\nIs everything okay with the Maxx A. Million Mk. V?!", completion = "You did it!  You did it!  I could just kiss you!\n\nOh, darn... the Maxx A. Million Mk. V is out of juice again.  Ah well, he had enough to get the job done, and that's what counts!\n\nRocket-Chief Fuselage will be pleased to get these draenei machines hooked up inside the X-52 Nether-Rocket!  That means a promotion for me!  I'm so happy, I just have to give you a reward!\n\nHere, take your pick from one of these.", sourceObjectiveStatus = "unverified-source-field" }
quests[10192] = { id = 10192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasus's Compendium", description = "The Kirin Tor sent one other of Krasus's possessions with our expedition. It was his spellbook, called Krasus's Compendium. Containing all the spells he mastered, it lent us a much-needed advantage in the war.\n\nBefore Kael'thas and his forces laid siege to Kirin'Var, the compendium had been stolen from me by a rebellious apprentice intent on studying necromancy. The apprentice and his followers divided and studied the text in secret, locking themselves inside their houses in the southern part of town.", sourceObjective = "Reclaim Krasus's Compendium - Chapter 1, Krasus's Compendium - Chapter 2, and Krasus's Compendium - Chapter 3 from Kirin'Var Village's Town Square.", progress = "Have you brought the book?", completion = "<Archmage Vargoth's image seems to inspect the compendium.>\n\nIt's a little worse for the wear, but considering the treatment it's been through, it's a miracle all of it survived. Safeguard it, {name}. Without it, we stand little chance of being able to break the tower's ward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10193] = { id = 10193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Value Targets", description = "Based on the roster information, we know that the brains of the manaforge operations are the warp-masters and warp-engineers.  It is they who oversee the retrieval of a so called \"warp-energy\" by the manaforge and its delivery to a remote destination via a system of underground pipes.\n\nThe only other specialists in the area are geologists.  Everyone else is either part of the military or a magister crony; both easily replaced.\n\nGet in there and kill Kael's specialists; that's what'll hurt him the most.", sourceObjective = "Spymaster Thalodien at Area 52 wants you to go to Manaforge B'naar and slay 2 Sunfury Warp-Masters, 6 Sunfury Warp-Engineers and 8 Sunfury Geologists.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", completion = "You're one reliable fellow, {name}.  If there's one thing I like more than killing Kael's lapdogs, it is having someone else do it for me.\n\nLess blood on my clothes that way.", sourceObjectiveStatus = "unverified-source-field" }
quests[10194] = { id = 10194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealth Flight", description = "While you were gone, my men uncovered another one of these manaforges.  It is east of here and is known as Manaforge Coruu.\n\nTwo of my best spies have arranged a secret landing spot outside of the manaforge.  You are to help them infiltrate Kael's forces and obtain whatever information you can.\n\nSpeak to Veronia just outside the city walls; she's arranged for a windrider that will take you to Manaforge Coruu.  Once there, speak to Caledis Brightdawn; he will brief you on your mission.", sourceObjective = "Speak to Veronia outside Area 52 and fly to Manaforge Coruu.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", completion = "Arranging for your flight wasn't cheap.  Let's hope you have what it takes to get the job done.", sourceObjectiveStatus = "unverified-source-field" }
quests[10196] = { id = 10196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Arakkoa Feathers", description = "I've had some success drawing the arakkoa spirits closer to me, but they are still very shy. Perhaps if I improve my disguise, they will be more willing to approach me in the trance.\n\nTo do that, though, I'll need more feathers like the ones you've already brought me. If you get any more of the feathers, I'd be very happy to take them off your hands.", sourceObjective = "Bring 30 Arakkoa Feathers to Malukaz at Stonebreaker Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10197] = { id = 10197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Convincing Disguise", description = "Infiltrating the ranks of Kael's army will not be an easy task.  With my knowledge of illusionary magic I could pass you off as one of Kael's followers, but there are certain details in their uniforms I could not replicate.\n\nBring me a set of their robes, a pair of their gloves and a Sunfury guardsman medallion.  This will make the results of my magic much more convincing.", sourceObjective = "Obtain a set of Sunfury Arcanist Robes, one pair of Sunfury Researcher Gloves and a Sunfury Guardsman Medallion and bring them to Caledis Brightdawn at Manaforge Coruu in Netherstorm.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Have you obtained the outfit pieces I asked of you?", completion = "Excellent!  When I'm through with you, you will be able to slip among the Sunfury ranks unnoticed.", sourceObjectiveStatus = "unverified-source-field" }
quests[10198] = { id = 10198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Information Gathering", description = "I've prepared a uniform with the pieces you obtained.  It is magically enhanced to complete the illusion.\n\nWe spotted Commander Dawnforge going in to meet Arcanist Ardonis a few minutes ago.  He had a full retinue of guards with him, so whatever they're discussing is bound to be incredibly important; see if you can catch any of it.\n\nOh, I almost forgot.  You'll want to stay away from the arcane golems patrolling the manaforge.  They will see right through the illusion.", sourceObjective = "Use the Sunfury Disguise, go into Manaforge Coruu and listen to the conversation between Commander Dawnforge and Arcanist Ardonis.\n\nCompleting tasks for the Scryers will cause your Aldor reputation level to decrease.", progress = "How goes the eavesdropping, {name}?  You'd best hurry.  I'm getting antsy here.", completion = "Manaforge Duro is in trouble?  I'm sure Thalodien will love to hear the news.  Let's wrap up the job here first.", sourceObjectiveStatus = "unverified-source-field" }
quests[10199] = { id = 10199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Little Extra Kick", description = "So, I'm just missing the one ingredient that'll give my concoction that little extra kick that it needs.\n\nThe sting of the nether rays, roaming around near the shaleskin flayers, delivers quite a punch.  Bring me some of their stingers and I'll extract the venom right out of them!\n\nI'm certain the results will be explosive!", sourceObjective = "Obtain 5 Nether Ray Stingers for Boots at Area 52 in the Netherstorm.", progress = "If I can drain the venom from enough of those nether ray stingers, I think we might just have the most explosive fuel ever devised!", completion = "Wow!  Alright, now we're talking!\n\nLet me just take those little beauties and squeeze the badness right out of them.  This should make a rocket fuel brew that'll blow everyone's socks off!\n\nHere, just let me mix the shale oil and this stinger venom together, and we'll see what happens....", sourceObjectiveStatus = "unverified-source-field" }
quests[10200] = { id = 10200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Thalodien", description = "It would be best if this information got back to Thalodien as soon as possible.  I'll stay here and cover our tracks.\n\nIt wouldn't do us much good to have Kael'thas find out what we were snooping around here.  Secret information is always better if your enemy doesn't know you have it.", sourceObjective = "Return to Spymaster Thalodien at Area 52 in Netherstorm.", completion = "You do not cease to amaze me, {name}.  That was quite the feat of stealth you pulled off at Manaforge Coruu.", sourceObjectiveStatus = "unverified-source-field" }
quests[10201] = { id = 10201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Now, the Moment of Truth", description = "The oil is finally ready for its first test. It seems heavy enough to serve as a high quality weapon oil.\n\nThe only way to find out is to have a professional try it out. See Grek over there by the wanted posters? Sure, he's no poet, but the orc knows his way around a weapon!\n\nTake a sample of the oil to him and ask him to use it on his weapon. After he's had a chance to test it out, let me know what he thinks of it.", sourceObjective = "Find Grek and ask him to try it on his weapon. Once he's tried out the oil, return to Rakoria with the results.", progress = "Well, do you have the test results?", completion = "<You tell Rakoria the results of the test and she throws her head back, laughing.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10202] = { id = 10202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Defector", description = "We've recently been contacted by a Sunfury magister who wishes to join our ranks and swears he has information we're in need of.  We've checked our informants to make sure he's not a double agent and he checks out.\n\nHe's stationed in Manaforge Ara which makes communication difficult.  Talk to him and see what he knows.  If he's half as useful as he claims to be, we'll be able to put him to good use.", sourceObjective = "Go to Manaforge Ara and speak to Magister Theledorn.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", completion = "It's about time you showed up.  I was beginning to wonder if the Scryers were interested at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[10203] = { id = 10203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invaluable Asset Zapping", description = "See the fissure running through Area 52?  We did that!  <grin>\n\nIt's yielding up all sorts of goodies for the X-52 Nether-Rocket, but we're running short on equipment.\n\nWe had an operation at the Arklon Ruins to the southeast until the Burning Legion moved in.  I need you to take this Ultra Deconsolodation Zapper to the ruins.  Use it to beam our gear back to Lead Sapper Blastfizzle down in the fissure.\n\nJunior Technician 3rd Grade {name}, this is your chance for that promotion.  Don't blow it!", sourceObjective = "Use the Ultra Deconsolodation Zapper to beam the Hyper Rotational Dig-A-Matic, Servo-Pneumatic Dredging Claw, Multi-Spectrum Terrain Analyzer, and the Big Wagon Full of Explosives back to Area 52. Then report to Lead Sapper Blastfizzle at the eastern end of the fissure that runs through Area 52 in the Netherstorm.", progress = "Isn't this place great?  And everyday yields something new and exotic!\n\nWhat a stroke of luck that we nearly destroyed the town digging down here.", completion = "You must be the one that zapped all of that sapping equipment back to us here from the ruins!  Hooray for you!\n\nI've already reallocated the equipment out to our other locations.  Now we'll be able to expedite our fissure operations on this whole island by an order of magnitude!  The nether-rocket will be completed in no time!\n\nHmmm, that's odd.  Wait a minute, did you say that you sent four things back to us?  I only got three...", sourceObjectiveStatus = "unverified-source-field" }
quests[10204] = { id = 10204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodgem Crystals", description = "Kael's magisters have refined their usage of mana crystals to the point where they can siphon large amounts of energy in a matter of seconds.\n\nThey do this by attuning smaller bloodgem crystal shards to larger, fully charged ones.\n\nGo to Manaforge B'naar and obtain one of these shards from a Sunfury magister and use it to siphon energy from one of the larger crystals.\n\nReturn to me so that I may study the effects of the aura.  Do not worry; any side effects should be temporary.", sourceObjective = "Magistrix Larynna wants you to go to Manaforge B'naar and obtain a Bloodgem Shard from a Sunfury Magister. Use this shard near the larger Bloodgem crystals and return to her at Area 52.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", progress = "Did you investigate the bloodgems used by the Sunfury magisters, {name}?", completion = "Hmmm... just as I suspected.\n\nExposure to this level of raw energy greatly magnifies our innate addiction to magic.\n\nI'm not surprised Kael gets away with what he does; all his subordinates are basically drunk on this.", sourceObjectiveStatus = "unverified-source-field" }
quests[10205] = { id = 10205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warp-Raider Nesaad", description = "Warp-Raider Nesaad must be dealt with!  I have no idea how he survived my attack, but he cannot be allowed to continue his operation out there.\n\nGo back and take out Nesaad.  He keeps a small ethereal camp near the southwestern corner of the Heap.\n\nDon't fail like I did, {class}.", sourceObjective = "Kill Warp-Raider Nesaad and then return to Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", progress = "It's over then?  Warp-Raider Nesaad is dead?", completion = "It's a relief to hear that scum is finally dealt with.  You do good work, {name}... may I be so forward as to call you by your name?\n\nIf you're willing, I have another task that needs doing.  One that is very important and someone of your obvious skill should be able to handle with ease.", sourceObjectiveStatus = "unverified-source-field" }
quests[10206] = { id = 10206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pick Your Part", description = "Those ethereal clowns are as opportunistic as us, I'll give them that.  But no one, and I mean NO ONE, moves in on a B.O.O.M. claim!\n\nThe Heap to the south is ours!\n\nIf we're to finish the X-52 Nether-Rocket, we're going to need all of the new tech that we can get our hands on.  And since the ethereals are stealing from us, I think it's only fair that we repay them in kind.\n\nWhy don't you head down there and see if you can acquire some of their technology out from under their noses!", sourceObjective = "Collect 10 pieces of Ethereal Technology and return them to Papa Wheeler at Area 52 in the Netherstorm.", progress = "Back with their tech so soon?  You better not just be pulling my leg here, {class}.\n\nThe success of the X-52 project out here depends upon you getting us that stuff a.s.a.p.!", completion = "Hehe, ethereal suckers!\n\nThanks for getting us these parts, {class}.  I bet we can just hook these babies right up inside the rocket.  I wonder what they do?  Should be fun finding out!\n\nHmm, let me see if I can dig up some pocket change to throw your way.", sourceObjectiveStatus = "unverified-source-field" }
quests[10207] = { id = 10207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forward Base: Reaver's Fall REUSE", description = "Your battle prowess has been noted by high command, {class}. They want to send you to the front lines to meet up with Maimfist's crew. They're radicals, devoted to the complete extermination of the Burning Legion, so you may fit right in...\n\nHead east about 200 paces and veer south at the jutting mass of land. You'll see Reaver's Fall where an old farm used to stand. Once there, you are to report to Foward Commander To'arch.\n\nNow move out!", sourceObjective = "Report to Forward Commander To'arch at Reaver's Fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[10208] = { id = 10208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt Their Reinforcements", description = "Directly east of here is the Legion Front.  Spaced across the front are infernal portals and gateways, used to bring reinforcements to Hellfire Peninsula and throughout Outland. We're going to destroy those portals!\n\nTake these primers.  Designed in Area 52, they use the demons' own power as an explosive!  Defeat Legion forces around Portals Xilus and Kruul to gather demonic rune stones, use the primer to detonate four stones inside the portals, and watch!  Return to me when your mission is complete.", sourceObjective = "Defeat enemies around Portal Xilus and Portal Kruul to gather Demonic Rune Stones.\n\nUse To'arch's Primer within Portal Xilus and Portal Kruul.\n\nReturn to To'arch with To'arch's Primers at Reaver's Fall in Hellfire Peninsula.", progress = "The Legion won't be prepared for the surprise you have for them, eh {name}?", completion = "Well done!  I could almost feel the tremors of the explosions from here!\n\nNow, we have one more bombing mission for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[10209] = { id = 10209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoner Kanthin's Prize", description = "The next thing we must do is reclaim my familiar, Glacius, from the blood elf summoner who holds it captive. Summoner Kanthin was one of the most senior magisters in the force Kael'thas sent to decimate Kirin'Var. It's only natural that he would claim my familiar as a kind of trophy.\n\nI'm certain that Kanthin, fool that he is, has tried to compel Glacius to serve him. My scrying has revealed that Kanthin is now stationed at 'Manaforge Duro,' if that terminology has any meaning for you.", sourceObjective = "Defeat Summoner Kanthin at Manaforge Duro, on the island to the north of Sunfury Hold, and reclaim the Stone of Glacius from him.", progress = "Have you secured the Stone of Glacius?", completion = "<You're not sure whether it's just distortion, or the archmage really is smiling.>\n\nWith the last of my possessions restored, I have everything I need to break through Kael'thas's magic. I'll begin working the spell right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[10210] = { id = 10210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A'dal", description = "Welcome to Shattrath City, {class}.  This might be the one place in all of Outland where you'll find any semblance of safety.\n\nA group of naaru known as the Sha'tar drove the demons away from here.\n\nIf you've never met a naaru, you ought to see A'dal inside the Terrace of Light.  The leader of the Sha'tar is an awe-inspiring sight if I ever saw one.  Sure is a change of pace from anything else in this bleak land.", sourceObjective = "Speak to A'dal, the leader of the Sha'tar, in the center of the Terrace of Light.", completion = "<The light that filled your senses as you approached A'dal intensifies as you address him.  Melodic chimes continue to ring within your head.>\n\n<You are safe here.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10211] = { id = 10211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "City of Light", description = "Do not burden A'dal with petty inquisitions, {class}.  That just might be the most powerful being you ever come face to face with.\n\nYou do not look familiar.  I suppose you want to learn about the city?\n\nYou'll have to excuse me if I don't give you a tour myself, but I'm a bit busy discussing strategy with A'dal.  Perhaps you'll find a summoned servant acceptable in my stead?  Excellent!", sourceObjective = "Follow Khadgar's servant and listen to its story. Return to Khadgar after completing this task.", progress = "The stories of men are ephemeral, {name}.  The stories of cities last well into the years.", completion = "I hope you learned a thing or two about Shattrath, {name}.  It might take some time for things to sink in.", sourceObjectiveStatus = "unverified-source-field" }
quests[10212] = { id = 10212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero of the Mag'har", description = "I must set things in order before I leave. Return to the Greatmother and tell her that her grandson comes.", sourceObjective = "Return to Greatmother Geyah at Garadar in Nagrand.", completion = "You are truly the hero of the Mag'har, {name}. If not for you, we would have surely been overrun by the ogres and Broken.\n\nWe are a poor people but we do have some artifacts of power. Please, I insist that you take from our coffer.", sourceObjectiveStatus = "unverified-source-field" }
quests[10213] = { id = 10213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigate the Crash", description = "When I was wounded in the wastes I saw a goblin zeppelin crash.  It went down to the northwest, beyond the Expedition Armory. \n\nThe zeppelin was on fire.  Shrieking, burning goblins were falling like bombs from the sky.  Of course I was in a lot of pain and I had lost a lot of blood.  I may have imagined the whole thing.\n\nIf you can find any survivors, we can offer them sanctuary here at Spinebreaker Post.", sourceObjective = "Search for crash survivors.", completion = "We were shot down by the Burning Legion, even though we waved a flag of truce.  Who knew the Burning Legion was so mean? \n\nWe cannot come with you to Spinebreaker Post.  We need to repair our zeppelin and be on our way.", sourceObjectiveStatus = "unverified-source-field" }
quests[10214] = { id = 10214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When This Mine's a-Rockin'", description = "The mine's been overrun by a plague of gan'arg misfits, and on top of that, the peons have decided that this is a fine time for a nap! I don't know how they can sleep through all the disurbances coming from the mine, but that's the least of my problems.\n\nIf we don't get rid of those gan'arg pests soon, Thrallmar's supply of ore and other minerals will be cut off. I've already asked Watch Commander Krunk for help, but he says he can't spare the men with the town under constant attack. Will you help?", sourceObjective = "Kill 15 Gan'arg Sappers and return to Foreman Razelcraz.", sourceObjectiveStatus = "unverified-source-field" }
quests[10216] = { id = 10216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety Is Job One", description = "Shaffar's ethereals have completely blocked us out of the Mana-Tombs. Thankfully, I've got a plan. While we can't go in through the front door, there are sure to be several transporters inside.\n\nI want you to clear the way for my crew first and then I want you to activate one of their transporters to teleport us inside.\n\nActivate the teleporter in the chamber right before Shaffar's chambers when the way has been cleared. Don't worry, I'll make it worth your while...", sourceObjective = "Artificer Morphalius wants you to kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers and 5 Ethereal Spellbinders.\n\nOnce that's done, find the Ethereal Transporter in the chamber before Shaffar's and activate it.", progress = "This device has over a dozen buttons, none of which look familiar to you.", completion = "<You close your eyes and press a button.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10218] = { id = 10218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone Else's Hard Work Pays Off", description = "Who were you expecting!? That idiot Morphalius was 'de-prioritized.' Now I'm here to clean up his mess. All I need from you is to watch my back as I go through Shaffar's ether gatherers and suck them dry of all that they have collected. If I successfully complete my mission, Haramad himself will reward you!\n\nWhat do you say? Escort me through the Mana-Tombs and then collect some incredible treasure? You already did most of the work anyway! Nothing's alive back behind us, right?", sourceObjective = "Escort Cryo-Engineer Sha'heen safely through the Mana-Tombs so that he can gather the ether held inside Shaffar's ether collectors.\n\nReport to Nexus-Prince Haramad located outside the Mana-Tombs at the Consortium encampment should you succeed.", progress = "Hello, little flesh beast.", completion = "Seeing as how this was Morphalius's idea, I decided to give him his old job back. Well done little flesh beast. Well done, indeed!\n\nRemember, if you're ever looking for work and happen to be in Netherstorm, come find me at the Stormspire.", sourceObjectiveStatus = "unverified-source-field" }
quests[10220] = { id = 10220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Them Listen", description = "I was sent here to make contact with the Unyielding spirits.  These once proud Alliance soldiers were defeated long ago, and now their cursed spirits haunt the ruins to the west.  \n\nIf they would only join us we would gain a powerful ally.  Imagine, a legion of undying warriors to use against our enemies.  But these undead are mad with hatred and will not listen to me.  \n\nPerhaps they can be forced to join us.", sourceObjective = "Mordiba wants you to defeat 12 Unyielding Footmen, 8 Unyielding Knights, and 6 Unyielding Sorcerers at the Expedition Armory to the west of Spinebreaker Post.", progress = "Have you taught the Unyielding the consequences of defying the Forsaken?", completion = "The Unyielding have felt the strength of the Horde.  No doubt they will soon be in the mood to listen to my proposed alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10221] = { id = 10221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dr. Boom!", description = "{name}, my former protege, Sparky Uberthruster, wouldn't wear his helmet while down here and one day transformed into the infamous Dr. Boom!\n\nAnd he stole off to the northeast with most of our sapping equipment!  He and his Boom Bots have been a menace to Area 52 ever since.\n\nI need you to go to his Camp of Boom just outside of town and put an end to him!  Use these Boom's Doom bombs to take him out.\n\nAnd make sure not to get too close to him or his Boom Bots!", sourceObjective = "Kill Dr. Boom and return with the good news to Lead Sapper Blastfizzle at Area 52 in the Netherstorm.", progress = "Have you saved us from the depredations of Dr. Boom?  I promise this time there won't be any exploding wagons, though that was a lot of fun!\n\nWe really should do that more often.", completion = "I'll always miss Sparky.  <sniff>  But we'll all sleep better now knowing that as Dr. Boom he is no longer around to terrorize us!\n\nJust let this be a lesson to you.  Don't come down here without a nether helmet!\n\nNow, how can I repay you?", sourceObjectiveStatus = "unverified-source-field" }
quests[10222] = { id = 10222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunfury Garrison", description = "After Prince Kael'thas's forces destroyed the village and imprisoned the archmage in the Violet Tower, they withdrew to Sunfury Hold to the northeast. The very men who destroyed our village and slew our fellows toast their 'amazing victory' while we are helpless to avenge the fallen.\n\nWe must not allow these crimes to go unanswered! Be the instrument of our vengeance, {name}. Go to Sunfury Hold and claim the lives of those responsible for this crime.", sourceObjective = "Custodian Dieworth at Kirin'Var Village wants you to kill 10 Sunfury Archers.", progress = "Is it done, {name}? Have you avenged the fallen of Kirin'Var Village?", completion = "What you've done this day can never bring back the fallen, but perhaps it can help soothe their spirits. Although, truth be told, no amount of blood can quench my anger over the actions of Kael'thas.", sourceObjectiveStatus = "unverified-source-field" }
quests[10223] = { id = 10223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down With Daellis", description = "I'll never forget the blood elf who led the attack. He wore a tabard with a device I've never seen before, over top of crimson armor.\n\nHe was ferocious and merciless, leading from the front where most other blood elf officers would never be seen. He was responsible for the deaths of many Kirin Tor mages that day, but he didn't linger long at Sunfury Hold. Kael'thas has ordered him to Manaforge Duro to aid in their attempt to control the area. Find him, {name}, and silence his bow for good.", sourceObjective = "Custodian Dieworth at Kirin'Var Village wants you to kill Master Daellis Dawnstrike.", progress = "Have you finished the task, {name}?", completion = "<You're not certain, but it seems as though Custodian Dieworth is on the verge of tears.>\n\nAt last, it is through. If I could will myself out of existence, I would, but the truth is I don't know how to let go. For the ones in the village, it is difficult but straightforward. I suppose this is the price we pay for retaining such strong ties to this place.", sourceObjectiveStatus = "unverified-source-field" }
quests[10224] = { id = 10224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence for the Engines", description = "As the X-52's chief of engineering, I have to see to it that the nether-rocket's main engines are in tip-top shape.\n\nUnfortunately, I haven't built them yet.\n\n{class}, I'm in dire straits here!  I have almost all of the parts.  All that I'm missing is the engine core.\n\nLuckily for us, I think we can make use of the essence from the local mana wraiths to jump-start the engines.\n\nThey can be found near most of the glowing trenches in the northern part of the island.  Except for here in Area 52, of course.", sourceObjective = "Collect 7 Mana Wraith Essences and return them to Chief Engineer Trep at Area 52 in the Netherstorm.", progress = "You have all of those essences yet?", completion = "Wow, that's a lot of essence!\n\nOk, let's see what happens when I mix it with the etherlithium matrix crystals.", sourceObjectiveStatus = "unverified-source-field" }
quests[10225] = { id = 10225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Engineering", description = "{name}!  I need you to take all of these etherlithium crystals over to Chief Engineer Trep, my, uh, chief of engineering.\n\nHe should know what to do with them.  And if he doesn't, you see to it that he finds out!", sourceObjective = "Deliver the Etherlithium Matrix Crystals to Chief Engineer Trep at Area 52 in the Netherstorm.", progress = "Um, hi.   I'm a little busy here.  What's that you have there?", completion = "Ooh, etherlithium matrix crystals.  Yeah, those sound important!\n\nLet's just put them over here and I'll get to figuring them out in a moment.", sourceObjectiveStatus = "unverified-source-field" }
quests[10226] = { id = 10226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Power Extraction", description = "Darn it, that didn't do it!\n\nOk, I've got another idea!  I had Xyrol whip up an elemental power extractor.  I'm not certain exactly what this power will do, but I know that I can use it.\n\nThe sundered rumblers and warp aberrations on the ledge of the Crumbling Wastes to the south have just what I need for the engines!\n\nThe extractor will change the form of their power into something solid that you'll be able to gather up after you've defeated them.", sourceObjective = "Extract 5 Elemental Power for Chief Engineer Trep at Area 52 in the Netherstorm.", progress = "You have the power from those elementals yet?  Oh, don't hurry or anything.  It's just my life and career on the line.", completion = "That's more like it!  Alright, now I think we're in business.\n\nJust let me dump this stuff into the thing-a-ma-jig here and I'm sure it'll spit out a fully functioning phase engine core.\n\nOh, hey, I guess I ought to reward you for saving my neck!  Hehe.", sourceObjectiveStatus = "unverified-source-field" }
quests[10227] = { id = 10227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I See Dead Draenei", description = "I see dead draenei. They're all around us.\n\nBah, nobody believes me because I'm a child. Not even my own mommy believes me.\n\n<Ha'lei points to Ramdor.>\n\nHe believes me, though... He sees them too. Boy does he get angry about it!\n\nIt's kind of funny. I see ghosts and people just smile and pat me on the head, trying to placate me. Ramdor sees ghosts and people label him as crazy. I sure hope I never grow up!\n\nYou should probably talk to Ramdor before you go inside. He was once a death priest.", sourceObjective = "Speak to Ramdor the Mad, standing on the bone pile outside of the Auchenai Crypts.", completion = "The child is correct. I was once a \"death priest.\"\n\n<Ramdor winces.>\n\nSuch an unsavory title.\n\nThrough that corridor lies the Auchenai Crypts. Inside you will find the remnants of my priory. They are all mad now, of course. Insane to the last! I suppose I stood out, being the last one among them with any common sense. Of course, I was excommunicated for my beliefs.\n\nWhat are my beliefs, you say?", sourceObjectiveStatus = "unverified-source-field" }
quests[10228] = { id = 10228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ezekiel", description = "I believe that the dead, which we have been caring for these last 500 odd years, should be left alone. Maladaar has other plans. He has retreated to the Crypt of Remembrance to start his experiments... Necromancy.\n\nI hope you weren't thinking about going in there... Not before helping me out so that these damned spirits will finally leave me alone. I know where they keep their treasures, {race}. Got your attention, eh?\n\nBring me the book of the dead, held by the Aldor, Ezekiel of Shattrath.", sourceObjective = "Find and speak with Ezekiel of Shattrath in Shattrath City.", completion = "Book of the dead? Never heard of it... What's this about anyway? Who sent you?", sourceObjectiveStatus = "unverified-source-field" }
quests[10229] = { id = 10229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decipher the Tome", description = "This tome appears to be some sort of history written in a secret Alliance cipher.  Althen, the historian in Spinebreaker Post, has studied the Unyielding for some time; he may be able to crack the Alliance code and decipher the book.", sourceObjective = "Take the Mysterious Tome to Althen the Historian in Spinebreaker Post.", progress = "What is this?  A book carried by an Unyielding spirit?  How strange.  Let me study it.  Perhaps I can learn the history of the Unyielding.", completion = "I have studied ancient history my entire un-life.  I have never seen anything like this book.  It tells the entire history of the Armory, including events that happened after its destruction.  \n\nThe Unyielding have kept their history, even after they had fallen in battle.  With this book we will be able to understand the Unyielding and convince them to join us.", sourceObjectiveStatus = "unverified-source-field" }
quests[10230] = { id = 10230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Horn", description = "Perhaps we have taken the wrong approach to the Unyielding? \n\nThe tome tells me the Expedition Armory was destroyed by orcs and death knights long ago.  The Unyielding remain here as vengeful spirits trapped in an eternal battle against the fel orc clans.  \n\nThey think only of revenge.  We must arrange for them to defeat their most hated enemies.  Enter the Expedition Armory once again and find Lieutenant Commander Thalvos.  He carries a battle horn that can summon the Unyielding.  Bring it to me.", sourceObjective = "Take the Unyielding Battle Horn from Lieutenant Commander Thalvos and bring it to Althen the Historian in Spinebreaker Post.", progress = "We must help the Unyielding soon.  If we can convince them to join us the Horde will have gained a powerful ally.", completion = "You have done well {name}.  This ancient horn will allow us to summon the Unyielding. \n\nThat is, if they are willing.", sourceObjectiveStatus = "unverified-source-field" }
quests[10231] = { id = 10231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Book? I Don't See Any Book.", description = "Ramdor? Hrm, let me think... Ramdor... Oh yes, the death priest. What does he want with the book? Well it doesn't matter. Yes I lied to you and no I don't have the book. Not anymore, anyway. It was stolen. Probably by one of those filthy refugees.\n\nBesides, Auchindoun is now defunct. We have no use for the book. If you find it, you can keep it.\n\nLike I said, I saw some of those ruffians snooping around the terrace last week. Start your search with them. They're probably playing dice in the slums.", sourceObjective = "Ezekiel said the book has been stolen. Your best bet is to find the Ruffians and see if they have any information.", progress = "Whaddya want?", completion = "Ok, ok! Don't hurt us. We had the book but we sold it...", sourceObjectiveStatus = "unverified-source-field" }
quests[10232] = { id = 10232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In A Scrap With The Legion", description = "The Burning Legion has moved in on our claim at the Scrap Field down the path and across the bridge to the east.\n\nThis could be a huge problem for us!  With the Legion at the Arklon Ruins, and now there, it's starting to look bad for us - and the rocket project - here at Area 52.\n\n{name}, I need you to go out there and deal with those demons!  I'd do it, but I'm a lover, not a fighter.\n\nYep, this is going to be trouble, I can feel it!", sourceObjective = "Kill 5 Mo'arg Doomsmiths and 15 Gan'arg Engineers. Then return to Papa Wheeler at Area 52 in the Netherstorm.", completion = "Well, that's good and bad news, now isn't it?  We've dealt them a blow, but with the Burning Legion running free all over the Netherstorm - and getting closer to us here - well, I don't know how it's going to go.\n\nI have a feeling that we're going to have to change gears here for a while.  Hope you'll be able to help us out, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10233] = { id = 10233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torching Sunfury Hold", description = "Ridding Sunfury Hold of its garrison is not sufficient to keep the blood elves from reoccupying it. Kael'thas's followers are zealous and tenacious. Leaving them anything to use at Sunfury is effectively an invitation to return.\n\nNo, it must all be destroyed. See to it that their tents and artillery burn to ashes!\n\n<The ghost's fists clench.>\n\nSteal torches from the Sunfury flamekeepers to accomplish your task, {name}.", sourceObjective = "Using a Flaming Torch, destroy 4 Sunfury Ballistas and 4 Sunfury Tents and return to Lieutenant-Sorcerer Morran at Kirin'Var Village.", progress = "Smoke rises from the Sunfury Hold fortifications. Is that your handiwork?", completion = "<Lieutenant-Sorcerer Morran nods grimly.>\n\nThe Kirin Tor hardly relish destruction for its own sake, but we have no qualms about acting against our enemies, even in death.", sourceObjectiveStatus = "unverified-source-field" }
quests[10234] = { id = 10234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Demon's Trash...", description = "You look like a capable young <man/woman>!  I was wondering if you could lend me a hand?\n\nTo the east is the Scrap Field, which the Burning Legion has moved into.  It's full of huge fel reaver parts.  There're also a whole bunch of smaller parts in there that they don't seem to care about.\n\nI want you to get in there and get me a lot of those smaller fel reaver parts!", sourceObjective = "Gather 10 Fel Reaver Parts and return them to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", progress = "You have those parts yet?  With the Burning Legion moving in on each of our claims around here one at a time, we unfortunately have little time.", completion = "These will have to do for now, I suppose.  If only we could scare them off.\n\nHey, that gives me an idea!", sourceObjectiveStatus = "unverified-source-field" }
quests[10235] = { id = 10235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Declawing Doomclaw", description = "You know what might just discourage them?  Take out their leader!\n\nIt seems to work everywhere else from what I've heard.  And when they see a <grizzled/tough> {class}, such as yourself take out their leader... why, I bet they'll tuck tail and run for the hills!\n\nGet back in there and take out the big one they call Doomclaw.  I hear he keeps himself in the eastern part of the Scrap Field underneath the pipe.\n\nBring me his claw, too!  Maybe we can make use of it.", sourceObjective = "Obtain Doomclaw's Hand and deliver it to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", progress = "Dealt with Doomclaw yet?", completion = "He, uh... he said what?  THEY'RE GONNA GO AFTER AREA 52?!\n\nOh, this is not good... not good!", sourceObjectiveStatus = "unverified-source-field" }
quests[10236] = { id = 10236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outland Sucks!", description = "I can't believe I left Booty Bay to come to Outland.  My cousin Screed Luckheed promised me I would make a fortune, but instead he flew off in his zeppelin and left me here to try to scrape a living out of this mine.  \n\nHow am I suppose to make a living here with helboars and demons and fel orcs attacking all the time?  My shredder here was broken yesterday and the parts I need to fix it were stolen by fel orcs.  They took the parts into the fissure to the southwest and may have dropped them there.", sourceObjective = "Find 6 Shredder Parts and return to Foreman Razelcraz by the mine northwest of Thrallmar.", progress = "Did you find some spare parts for my shredder?  I really want to get it fixed so I can get back to mining.  I have to make a living somehow, if only so I can buy a one-way ticket back to Booty Bay.", completion = "Hurray, you found some parts!  Now maybe I can get my shredder working.  If I earn enough money I might be able to get back to Booty Bay. \n\nI sure hope my cousin, Screed Luckheed, crashes that stupid zeppelin of his.  I can't believe he tricked me into coming to Outland.", sourceObjectiveStatus = "unverified-source-field" }
quests[10237] = { id = 10237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn Area 52!", description = "{name}, you have to get word back to Area 52 immediately!  Hurry!\n\nTell the rocket-chief that the Burning Legion is after us now!", sourceObjective = "Deliver the bad news to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", completion = "Heh, you're kidding, right?  The Burning Legion is blaming us for all of that?\n\nBut YOU'RE the one that did it!\n\nOy, I have a headache and it's as big as this rocket.  Okay, okay, this calls for a change of plans.\n\nIf the Burning Legion thinks that it's going to come here, destroy our town and ruin my dream of cruising through the Twisted Nether, they are sadly mistaken.\n\nAnd I know just the goblin to help us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[10238] = { id = 10238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Serve Goblins", description = "Why would fel orcs steal my shredder parts?  I hate them so much.  They just sneak into my camp here and take things all the time.  A couple of days ago they stole three of my peons!  Now the rest of my peons have run off because they are afraid they are going to be eaten by fel orcs.  \n\nI can't run a mine without peons.  If you could save the peons that I lost maybe the others would come back.  The fel orcs have their camps along the wall to the southwest.", sourceObjective = "Rescue Manni, Moh and Jakk from the Fel Orc camps and return to Foreman Razelcraz by the mine northwest of Thrallmar.", progress = "Have you saved my peons yet?  Please hurry, I'm afraid they are going to be eaten and they probably won't taste very good.  If they taste really bad the fel orcs might get really mad at me.", completion = "Thank you for saving my peons.  Now maybe I can get them to fix my shredder with those parts you found, earn some money and get out of Outland.  I can't wait to be back in Booty Bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[10239] = { id = 10239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potential Energy Source", description = "We are not the only ones battling the influx of the mana beings. The blood elves, too, are troubled by them, but I'm not sure why.\n\nWhatever they're involved in over there, they don't seem to be stopping. Instead, I've seen them employ a variety of methods to kill the creatures. The most effective involves magical defenses fueled by some sort of concentrated energy.\n\nCapture some of these energy sources and bring them to me. Don't hesitate to stymie the elves if an opportunity presents itself.", sourceObjective = "Lieutenant-Sorcerer Morran at Kirin'Var Village wants you to capture 10 Energy Isolation Cubes from the blood elf operations at Manaforge Coruu.", progress = "Were you able to gather any of their energy sources?", completion = "<Morran gingerly handles one of the containers.>\n\nI don't believe I've seen anything like this before. There's certainly a lot of energy suspended in here, but it's in a raw form. We'll have to be careful with it, but I think we can find a way to adapt this to help ward off the mana creatures.", sourceObjectiveStatus = "unverified-source-field" }
quests[10240] = { id = 10240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building a Perimeter", description = "We are prepared to try to construct a perimeter around the village using the energy source taken from the blood elves. I can't guarantee that it will work, but we have to attempt it.\n\nOtherwise, the mana creatures will surely continue devouring the spirits of the fallen Kirin Tor.\n\nUse this device at the small runes around the perimeter of town to release the energy there. If I've woven the field correctly, we should start noticing a difference once you've used the device at each point.", sourceObjective = "Use the Rune Activation Device near the East Rune, Northeast Rune, and West Rune. The runes can be found around the perimeter of Kirin'Var Village's Wizard Row and Town Square districts. Return to Lieutenant-Sorcerer Morran once you've completed the task.", progress = "Have you activated all the runes? I'm eager to see if we can't improve upon the blood elf method here. Anything one of Kael'thas's men can do, real Kirin Tor can do better.", completion = "Excellent work. Keep your fingers crossed, {name}. I'm going to activate the shield.", sourceObjectiveStatus = "unverified-source-field" }
quests[10241] = { id = 10241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Distraction at Manaforge B'naar", description = "We were sent here by the Sha'tar to investigate the manaforges that Kael'thas' army is operating here.  Unfortunately, the Scryers threaten to renege on their information-gathering duties unless we support them with military action.\n\nWe can't afford to compromise this mission over politics, so we've agreed to weaken the manaforge's defenses so that the Scryers can do their work.\n\nProve your loyalty to the Aldor and slay the Sunfury magisters and bloodwarders that guard Manaforge B'naar.", sourceObjective = "Slay 8 Sunfury Magisters and 8 Sunfury Bloodwarders and return to Exarch Orelis at Area 52.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Have you completed your task, {name}?", completion = "Excellent work, {name}.  The Scryers have uncovered valuable information thanks to your distraction.  Maybe they'll actually share it with us this time.", sourceObjectiveStatus = "unverified-source-field" }
quests[10242] = { id = 10242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinebreaker Post", description = "{name}, my equipment here is, unfortunately, not configured for all the tests I'd like to perform.  However, my colleague at Spinebreaker Post, Apothecary Albreck, possesses the required implements.\n\nI have acquired a sample of Bleeding Hollow blood -- gained from a past mission of Thrallmar's agents.  Take the sample to Albreck and allow him to study it.\n\nTo reach Spinebreaker Post, speak with Wing Commander Brack, near the wyverns to the south.", sourceObjective = "Apothecary Zelana at Reaver's Fall wants you to speak with Wing Commander Brack to take a wyvern to Spinebreaker Post, and then bring the Bleeding Hollow Blood Sample to Apothecary Albreck at Spinebreaker Post.", progress = "Welcome to Spinebreaker Post.  How might my talents serve you?", completion = "A blood test, is it?  It will be my pleasure.  I always enjoy working with blood...", sourceObjectiveStatus = "unverified-source-field" }
quests[10243] = { id = 10243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naaru Technology", description = "The Scryers obtained a personnel roster for Manaforge B'naar and are now having a field day picking out assassination targets.\n\nThey've missed one small bit of information, scribbled on the side of the roster.  It appeared to be a password or code like those used to access naaru-made technology like the Exodar or Tempest Keep.\n\nGo inside the manaforge and look for a control panel.  Copy its readouts on this scroll as well as you can.  We must confirm our suspicions about the origin of the technology.", sourceObjective = "Go inside Manaforge B'naar and find the B'naar Control Console.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "The symbols scrolling in front of you look alien and unintelligible.", completion = "You unwrap the scroll and ready yourself to copy down the strange symbols.", sourceObjectiveStatus = "unverified-source-field" }
quests[10244] = { id = 10244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "R.T.F.R.C.M.", description = "Cracking the seal on this rather large tome, you can't quite make out what the words say.  They appear to be written in the language of demons.\n\nHowever, you can make out the pictures, which tell their own story.\n\nThis is clearly a fel reaver construction manual, and you know for a fact that Mama Wheeler will want to take a look at it!", sourceObjective = "Take the Fel Reaver Construction Manual to Mama Wheeler at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", sourceObjectiveStatus = "unverified-source-field" }
quests[10245] = { id = 10245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "B'naar Console Transcription", description = "You try to transcribe the shapes as you see them flash across your eyes.  The results are less than exact, but should serve as adequate evidence to prove or disprove the Aldor's suspicions.", sourceObjective = "Deliver the B'naar Console Transcription to Anchorite Karja at Area 52 in Netherstorm.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", progress = "Let us see what you've brought to us, {name}.", completion = "You've done well, {name}.  Allow me a few moments to go over your transcription.\n\nYou have the priesthood's thanks, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10246] = { id = 10246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Manaforge Coruu", description = "Your success at Manaforge B'naar was quite noteworthy.  I'm sure that Anchorite Karja will ask you for a repeat performance at Manaforge Coruu next.\n\nWe've learned of a particularly important regiment of Sunfury arcanists and researchers being deployed there and I would like you to target them.  Succeed and you will deliver a crushing blow against our enemy's forces.", sourceObjective = "Travel to Manaforge Coruu and slay 8 Sunfury Arcanists and 5 Sunfury Researchers. Return to Exarch Orelis when you've completed this task.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", completion = "Excellent job, {name}.  With your dedication we're sure to defeat our enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[10247] = { id = 10247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doctor Vomisa, Ph.T.", description = "On the outskirts of town to the east are the Proving Grounds.  Our top experimentalist, Doctor Vomisa, has been toying with a combination of fel reaver, ethereal, and of course, goblin technologies there.\n\nThis is in no small part thanks to your gathering efforts Junior Technician 3rd Grade, {name}!\n\nGo to him; I know that he'll have a solution for saving Area 52.\n\nAnd since he's likely to use you as a test subject, if I were you, I'd bring some friends along just in case.", sourceObjective = "Speak with Doctor Vomisa, Ph.T. at the Proving Grounds in Netherstorm.", completion = "Well, well, it would appear that we are in luck, young man.\n\nI was just recently able to finish the construction of my latest invention, the Scrap Reaver X6000!\n\nAnd you're going to have the honor of helping me test it so that it can be used in defense of Area 52!", sourceObjectiveStatus = "unverified-source-field" }
quests[10248] = { id = 10248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You, Robot", description = "Doctor Vomisa, Ph.T. at your service.  Here, take this controller.  I want you to activate it and give my newly-invented Scrap Reaver X6000 a spin.\n\nJust stay nearby!  The controller is tied to my console here, and if you get too far away, the robot will cease to function.\n\nTry out everything... I'll be watching and calibrating its servos based upon your test run.", sourceObjective = "Activate the Scrap Reaver X6000 Controller and test out its capabilities. Then give your feedback to Doctor Vomisa, Ph.T at the Proving Grounds in the Netherstorm. Deal with any problems that arise.", progress = "What did you think?  Still needs some tweaking, eh?", completion = "Well, my boy that certainly was exciting!  And for my money, I'd say that the Scrap Reaver X6000 performed admirably, despite its rookie pilot.\n\nHehe, no, don't take offense, I was just kidding.  After all, you just saved Area 52 and the X-52 Nether-Rocket from certain doom!", sourceObjectiveStatus = "unverified-source-field" }
quests[10249] = { id = 10249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to the Chief!", description = "I'm certain that the rocket-chief is going to want to have a word or two with you!\n\nIf I were you, I wouldn't hesitate to get back to Area 52 and speak with him!", sourceObjective = "Report to Rocket-Chief Fuselage at Area 52 in the Netherstorm immediately!", completion = "{name}!  Or, should I say Junior Technician 1st Grade {name}?!  Oh hell, who am I kidding?  Skipping a grade isn't a good enough reward for what you've done.  I'm going to make you my first officer!\n\nYou've saved all of us, and more importantly the X-52 Nether-Rocket!  I could just kiss you... but I won't.\n\nInstead, please let me present you with the gratitude of Area 52.  Take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[10250] = { id = 10250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Vengeance", description = "East of here is an old destroyed Alliance siege tower.  Now scavengers loot it for old nails and bits of scrap.  Long ago, many Alliance warriors lost their lives at this tower and their banner was captured by Urtrak, a foul orc commander.\n\nBlow the Unyielding battle horn near the Alliance banner.  This will get the attention of Urtrak.  It may also summon forth warriors who fell in battle long ago.", sourceObjective = "Blow the Unyielding Battle Horn near the Alliance Banner. Kill Urtrak and then return to Althen the Historian at Spinebreaker Post.", progress = "Have you blown the horn by the siege tower yet?  We must do this soon.  Who knows when Thrallmar will have need of the Unyielding.", completion = "I am glad to hear that the Unyielding joined you in your battle.  I thought they might come to the sound of their own battle horn, but I could not be sure.  Perhaps we have given some of them the vengeance they so desperately crave.  \n\nYou have slain Urtrak and we must report your victory to Commander Hogarth in the Expedition Armory.  He will understand the risks you have taken on his behalf.", sourceObjectiveStatus = "unverified-source-field" }
quests[10251] = { id = 10251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Grand Design?", description = "A couple of draenei paid us a visit last night. They'd somehow learned that we had the book in our possession and made a very generous offer to \"take it off our hands.\"\n\nWe didn't ask them what they wanted with the book but the young one kept talking about \"the master's grand design,\" whatever that means.\n\nLook, I don't ask questions when money is in play. They gave us a lot of gold and we gave them the book.\n\nHe said that they lived in Nagrand - in the old Abandoned Armory, north of Telaar.", sourceObjective = "Find Nitrin the Learned at the Abandoned Armory in Nagrand.", completion = "The signs were all there but I turned a blind eye.\n\nThe Legion's grasp grows stronger every day. Even in these parts...\n\nHad I known... Had I known that my boy was communing with demons... They offered him power and then gave him a taste of that power. That was all that it took...\n\nThe book is gone. Taken by Levixus... His plans are known only to me and his dark master.\n\nStranger, I don't know if you've ever done right in your life, but know this: the boy must be stopped.", sourceObjectiveStatus = "unverified-source-field" }
quests[10252] = { id = 10252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision of the Dead", description = "It has already begun. Levixus stands atop the ruins of Auchindoun and reads from the book of the dead. He calls the dead out by name and, through demonic ritual, binds the tortured souls to his will. He will raise all of Auchindoun if given the chance!\n\nBut... you must first prepare. You cannot do battle with that which you cannot see.\n\n<Nitrin hands you a parchment.>\n\nBring me the items I require to brew the tincture. It will open your mind and allow you to see into the spirit world.", sourceObjective = "Nitrin at the Abandoned Armory in Nagrand wants you to bring him 1 Mountain Gronn Eyeball, 1 Flawless Greater Windroc Beak, and 1 Aged Clefthoof Blubber.", progress = "Levixus's army grows in size and power with each second that passes. You must hurry.", completion = "Stranger... I was not forthright with you. Once you drink this potion, you will forever see into the world of the dead. This recipe that you drink of is a rite of initiation for all death priests of Auchindoun. Many go mad after its effects have taken hold. Seeing the dead is ... shocking.\n\n<Nitrin puts the potion up to your lips.>\n\nDo you wish to continue?", sourceObjectiveStatus = "unverified-source-field" }
quests[10253] = { id = 10253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Levixus the Soul Caller", description = "Go now, {name}. You will find Levixus on the uppermost ruins of Auchindoun. Enter there from the southern reaches of the Bone Wastes. He stands amidst a storm of souls...\n\nDestroy him and take the book of the dead. Once you have the cursed book in your possession, destroy it! Destroy it so that such an atrocity can never again be made possible.", sourceObjective = "Destroy Levixus and take the Book of the Dead from his possession.\n\nDeliver the Book of the Dead to Ramdor the Mad standing outside the Auchenai Crypt entrance of Auchindoun.\n\nYou had a deal, remember?", progress = "Who are you and what do you want? Oh... It's YOU.", completion = "If the old draenei said to destroy the book, why didn't you?\n\n<Ramdor glares at you.>\n\nBah, what's the difference. You might be greedy but at least you're honest.\n\nMe on the other hand... I lied to get this book. I have no idea where these poor lost souls kept their treasure nor would I tell you if I did - however - I do have something for you. You did a good thing on this day. Perhaps a great thing... You should be rewarded.\n\nBy the way, welcome to the fold.\n\n<Ramdor points to the spirits.>", sourceObjectiveStatus = "unverified-source-field" }
quests[10254] = { id = 10254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Force Commander Danath", description = "<Marshal Isildor spits in the dust.>\n\nWell, time to earn your pay. Report at once to Force Commander Trollbane within the keep. He and his advisors will no doubt be heartened to see you.\n\n<Marshal Isildor salutes you stoically.>\n\nFor the Alliance!", sourceObjective = "Marshal Isildor wants you to report to Force Commander Danath Trollbane in Honor Hold.", completion = "Well met, my brother.  I'm glad you've come. I am Danath - leader of the Sons of Lothar, and force commander of this hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[10255] = { id = 10255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Antidote", description = "I think there's something we can use in the blood as the base of an antidote. Don't look at me like I've lost my mind!\n\nIt's a common theme in nature. Often, the cure for something can be derived from the toxin itself. That's just what I aim to do.\n\nRidding the boars of their demonic influence would probably eliminate their aggression and give us insight into how to best attempt to help other species.", sourceObjective = "Use the Cenarion Antidote on a Hulking Helboar and observe the results. Once you have the results of the experiment, return to Thiah Redmane at the Cenarion Post in Hellfire Peninsula.", progress = "Do you have the results of the experiment?", completion = "<Thiah Redmane's eyes widen as you describe the results of the experiment.>\n\nBut, how could that happen? I'm certain I prepared the antidote correctly!\n\nI've seen it work with spider and snake venoms, so why would it backfire here? Perhaps that's one of Outland's many peculiarities, {name}. I'd best pass this information along to my comrades.", sourceObjectiveStatus = "unverified-source-field" }
quests[10256] = { id = 10256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding the Keymaster", description = "In retrospect, I suppose I should've expected Kael'thas's magic to be this robust. He's always been a talented mage, but I've never seen anything like the power he wielded during the attack on the tower.\n\nThe ward keeps me from being able to scry out the force holding it in place, but it doesn't preclude you from scrying.\n\nYou'll require a focus, though. A crystal-bearing giant named Apex roams the plains to the west of Manaforge Duro. One of its crystals would make an excellent scrying focus.", sourceObjective = "Locate Apex and obtain Apex's Crystal Focus from him. Return to the Violet Tower and use Apex's Crystal Focus near Archmage Vargoth's Orb to discover who holds the key to breaking the tower's curse.", progress = "What did your scrying reveal?", completion = "<You describe the results of your scrying.>\n\nCommander Sarannis, you say? Hmm...\n\nShe's one of Kael'thas's advisors, but certainly not a mage. I remember her from the attack on Kirin'Var Village. I think your impressions are correct, {name}. She's not maintaining the curse personally, but she holds the key to it.", sourceObjectiveStatus = "unverified-source-field" }
quests[10257] = { id = 10257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capturing the Keystone", description = "It doesn't surprise me that Kael'thas has put the key to this ward in the hands of someone like Commander Sarannis. Prince Kael'thas is a great many things, but he is no simpleton.\n\nIn order to break this curse once and for all, you must enter Tempest Keep and claim the keystone.\n\nOnly once the keystone has been destroyed will I regain my freedom.", sourceObjective = "Venture into Tempest Keep's Botanica and retrieve the Keystone from Commander Sarannis. Bring it to Archmage Vargoth at the Violet Tower.", progress = "Did you obtain the keystone?", completion = "<The archmage's eyes light up when you hand him the stone.>\n\nAmazing! From what little I've seen of the fate of Farahlon, I'm not certain I want to go outside, but it's much better than being trapped here for the rest of my days.", sourceObjectiveStatus = "unverified-source-field" }
quests[10258] = { id = 10258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Fallen", description = "Hogarth, the commander of the Armory, is in the eastern tower.  You must report your victory over Urtrak to him.  Perhaps he will be friendly?  Of course he may try to consume your soul.  One can never tell with spirits such as these. \n\nThe Unyielding are still against us and will no doubt kill you if they can.  Be careful {name}.", sourceObjective = "Report to Commander Hogarth in the Expedition Armory.", completion = "We lost our battle against the fel orcs so very long ago. You have restored some of our lost honor by killing Urtrak. \n\nTake one of our weapons with you.  When you are fighting our most hated foes, use this weapon, and those who are free of our curse will come to your aid.  \n\nBefore you leave, those who died at the siege tower wish to honor you for destroying our enemies.", sourceObjectiveStatus = "unverified-source-field" }
quests[10259] = { id = 10259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Breach", description = "Battle rages non-stop at the portal!  The Argent Dawn is fighting a desperate fight -- and if we lose, then there will be no end to the demon's fire.\n\nHelp us, {name}.  Enter the breach and lend aid to our brothers and sisters.  Help stem this tide of darkness!  The Argent Dawn -- and the world -- needs you!", sourceObjective = "Kill 6 Invading Felguards and then return to Argent Emissary Proudwell.", progress = "Once again into the breach, my friend!", completion = "Thank you, {name}.  Among the chaos of battle, heroes burn bright against the darkness.  Your light shines true!", sourceObjectiveStatus = "unverified-source-field" }
quests[10260] = { id = 10260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netherologist Coppernickels", description = "You must have crossed the main bridge into Netherstorm from Blade's Edge.  Did you see Netherologist Coppernickels working with all of his crazy equipment there?\n\nStrange... I've been expecting a report from him and it's overdue.  He's probably forgotten.  You know those 'science' types.\n\nHead back out to the bridge and pin him down.  Don't accept any of his excuses, just get me that report.\n\nThanks!", sourceObjective = "Speak with Netherologist Coppernickels at the bridge leading into the Netherstorm from Blade's Edge.You must have crossed the main bridge into Netherstorm from Blade's Edge. Did you see Netherologist Coppernickels working with all of his crazy equipment there?\n\nStrange... I've been expecting a report from him and it's overdue. He's probably forgotten. You know those 'science' types.\n\nHead back out to the bridge and pin him down. Don't accept any of his excuses, just get me that report.\n\nThanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[10261] = { id = 10261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Annihilator Servo!", description = "WANTED:  1 Annihilator Servo to replace the failing one in my Long Neck Spectrum Analyzer.\n\nYou and your friends might want to check with the blood elves at Manaforge B'naar to the west to see if they have any spares.  They seem to have a few arcane annihilators roaming about.\n\nPlease deliver the servo in pristine condition to Papa Wheeler at Area 52.", sourceObjective = "Obtain an Annihilator Servo and deliver it to Papa Wheeler at Area 52 in the Netherstorm.", progress = "I hope that you're here concerning the wanted ad that I placed!", completion = "Woo hoo!  Do you know how hard these things are to come by?  It's not like I'm getting a regular shipment of parts out here.\n\nTell you what, as payment I want you to take something out of my box of junk.  I'm sure there'll be something in there you can use.  And if not, sell it.\n\nAlright, let me just take that off of your hands and get it into my Long Neck Spectrum Analyzer before the failing servo in it explodes!", sourceObjectiveStatus = "unverified-source-field" }
quests[10262] = { id = 10262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Heap of Ethereals", description = "There is something else that I want your help with.\n\nA group of ethereals, known as the Zaxxis, have cut their relationship with the Consortium and gone into business for themselves.  They've even cut deals with the Sunfury blood elves.  This will not be tolerated!\n\nI infiltrated their group at the Heap to the south.  But after I took out their leader, I had to escape here to Area 52.\n\n{class}, go down there and bring back their insignias.  Of course, not all wear them because they're cowards.", sourceObjective = "Collect 10 Zaxxis Insignias and return them to Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", progress = "Is it done?  Have you wiped the Zaxxis scum from the face of Outland and brought me their insignia?", completion = "These insignia are a good start.\n\nUnfortunately while you were at the Heap, one of my other agents amongst the Zaxxis sent word to me that Warp-Raider Nesaad still lives!", sourceObjectiveStatus = "unverified-source-field" }
quests[10263] = { id = 10263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assisting the Consortium", description = "The naaru of Shattrath City have been trying to find a means to bring the Consortium over to their way of seeing things.\n\nLuck would have it that the business relationship between the ethereals and the blood elves of the Netherstorm has recently soured.\n\nThere's a Consortium representative in town named Nether-Stalker Khay'ji who recently ran into trouble with a pack of renegade ethereals.  As a representative of the Aldor, I would like for you to help him in any way that you can.", sourceObjective = "Speak with Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", completion = "Hello, {race}.\n\nYou don't happen to be available for a recovery mission of some importance?", sourceObjectiveStatus = "unverified-source-field" }
quests[10264] = { id = 10264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assisting the Consortium", description = "The naaru of Shattrath City have been trying to find a means to bring the Consortium over to their way of seeing things.\n\nLuck would have it that the business relationship between the ethereals and the blood elves of the Netherstorm has recently soured.\n\nThere's a Consortium representative in town named Nether-Stalker Khay'ji who recently ran into trouble with a pack of renegade ethereals.  As a representative of the Scryers, I would like for you to help him in any way that you can.", sourceObjective = "Speak with Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", completion = "Hello, {race}.\n\nYou don't happen to be available for a recovery mission of some importance?", sourceObjectiveStatus = "unverified-source-field" }
quests[10265] = { id = 10265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consortium Crystal Collection", description = "Our leader, Nexus-Prince Haramad, has tasked me with the acquisition of a crystal artifact from the Arklon Ruins to the southeast.\n\nThey're old draenei ruins.  Unfortunately for both myself and the goblins here, the Burning Legion has decided to move in to perform their own excavation.\n\nIf you're willing to help me, go to the ruins and take the crystal artifact from the dreadlord named Pentatharon.", sourceObjective = "Obtain an Arklon Crystal Artifact and return it to Nether-Stalker Khay'ji at Area 52 in the Netherstorm.", progress = "I get the impression that the prince is looking for a particular crystal, but I'm not certain what it is.\n\nHave you already recovered the one from the dreadlord?", completion = "Let me have a look at that.\n\nHmm, there doesn't appear to be anything special about it.  I doubt this is it, though the manner in which you describe the Burning Legion's activities at the ruins, it sounds as if they're searching for something in particular as well.\n\nLet us hope that it's not the crystal that the nexus-prince wants so badly.", sourceObjectiveStatus = "unverified-source-field" }
quests[10266] = { id = 10266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Request for Assistance", description = "While you were at the Arklon Ruins, I received a request for assistance from one of our representatives out in the field.  It would appear that the Consortium is having some 'difficulties' in trying to recover property from the blood elves, which they refuse to pay for.\n\nPlease head east out of Area 52 and cross the bridge to the next island over.  You'll find my associate, Gahruj, at the Midrealm Post, just inside of Eco-Dome Midrealm.", sourceObjective = "Seek out and offer your services to Gahruj. He is located at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", completion = "Yes, it's true.  The blood elves have reneged on yet another purchase of goods that has already been delivered.\n\nAs Nether-Stalker Khay'ji has vouched for you, I am hopeful that you will be able to assist me in this matter.", sourceObjectiveStatus = "unverified-source-field" }
quests[10267] = { id = 10267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rightful Repossession", description = "Our business relations with the blood elves appear to be at an end.  A few weeks ago a large shipment of surveying equipment was delivered to them at Manaforge Duro.  They have refused to pay for it.\n\n{name}, I would ask that you pay the blood elves of Manaforge Duro to the east a visit.  They appear to be having some trouble with an infestation of mana creatures there, so take advantage of their preoccupation.\n\nI care not what happens to them, but I would very much like to see the return of our property.", sourceObjective = "Collect 10 Boxes of Surveying Equipment and return them to Gahruj at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", progress = "Do you have possession of the surveying equipment which the blood elves defaulted on?", completion = "Well, I for one am glad that this petty little business is behind us.  I cannot remember a time when the Consortium has had dealings with such boorish and untrustworthy beings.\n\nYou, however, seem to be very trustworthy, {name}.  Perhaps you wouldn't mind doing me one more favor?", sourceObjectiveStatus = "unverified-source-field" }
quests[10268] = { id = 10268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience with the Prince", description = "Nexus-Prince Haramad has conveyed to me that he is interested in the immediate return of this property to him personally.  I would greatly appreciate if you would deliver it in my stead.\n\nIt is a great honor to gain an audience with the nexus-prince, and I am sure that he would be keenly interested in hearing the tales of your adventures here in the Netherstorm.\n\nSeek out his chamber atop the Stormspire to the north.  He is often present as a holographic image, which you may address.", sourceObjective = "Deliver the Surveying Equipment to the Image of Nexus-Prince Haramad at the Stormspire in the Netherstorm.", progress = "Approach.", completion = "I welcome you to the Stormspire, {class}.  Please enjoy the hospitality of the Consortium.\n\nYou may place that equipment anywhere.  I suspect that you'll be picking it back up rather soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[10269] = { id = 10269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triangulation Point One", description = "There is another reason for the retrieval of the surveying equipment.  There is a crystal from draenei legend of great importance to me.\n\nIt is said that the crystal bestows god-like powers to its bearer!  But it is in danger of being unearthed by others - namely the Burning Legion.\n\n{name}, take the equipment and use it to find the first triangulation point.  We know it to be somewhere to the east near Manaforge Ultris.\n\nAfterward, check-in with my agent, Dealer Hazzin, on the Manaforge Ultris island.", sourceObjective = "Use the Triangulation Device to point your way toward the first triangulation point. Once you have found it, report the location to Dealer Hazzin at the Protectorate Watchpost on the Manaforge Ultris island in the Netherstorm.", progress = "Hello, traveler.  You come to Hazzin because you are in need of my goods?", completion = "<Dealer Hazzin lowers his voice to a whisper.>\n\nAh, I know of your mission.  It is one of great importance to Nexus-Prince Haramad!\n\nNow that we know the location of this first triangulation point, you must move swiftly to find the second!", sourceObjectiveStatus = "unverified-source-field" }
quests[10270] = { id = 10270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Not-So-Modest Proposal", description = "From the look on your face, I can tell you're a {race} who appreciates a good profit.\n\nI've built a reputation as a dealer in exotic goods, and I'm about to launch a new venture.\n\nI need a reliable subcontractor to procure the goods from the Celestial Ridge.\n\nFirst, you'll need to re-energize a teleport pad. There is a spare power pack in Access Shaft Zeon, which is on the south side of Manaforge UItris. The Protectorate is operating in there, so you may be able to follow their tracers to your goal.", sourceObjective = "Retrieve the Teleporter Power Pack and bring it to the Ethereal Teleport Pad on the Celestial Ridge to the east of Manaforge Ultris. Activate the pad and give the Teleporter Power Pack to the Image of Wind Trader Marid so he can install it.", progress = "Are you prepared to discuss business now, {name}?", completion = "This power cell should hold for our purposes. Once the money starts rolling in, we'll improve it even more.\n\nEnough with such things. Every moment spent in discussion translates to lost profit.", sourceObjectiveStatus = "unverified-source-field" }
quests[10271] = { id = 10271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting Down to Business", description = "As you've no doubt seen, the area is teeming with nether dragons in various stages of growth. All nether dragons, young and old, contain an essence that's highly desired by K -- err, by a client of mine.\n\nMost people aren't willing to risk their lives to gather it, so we've got the place to ourselves. You can start by gathering the essence from any of the creatures out here, but it's imperative that we start building a supply right away. Return to me once you have the first batch.", sourceObjective = "Charge the Essence Gatherer by using it on Nether Drakes or Nether Dragons on the Celestial Ridge, then return to the Ethereal Teleport Pad area.", progress = "I'm certain you have many questions, all of which will be answered in due time.", completion = "And to think, that wretched ethereal was going to sell these essences to the blood elves like so much candy...", sourceObjectiveStatus = "unverified-source-field" }
quests[10272] = { id = 10272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Promising Start", description = "We've come here to investigate rumors of a strange breed of dragons, perhaps even descendents of Deathwing himself. These are clearly not ordinary black dragons, though.\n\nWe'll know more once we've had a chance to examine their eggs. Their hatred for my flight runs deep, so I can't get close enough to gather the eggs. Will you agree to help?", sourceObjective = "Gather 15 Nether Dragonkin Eggs, then return to Tyri and Jorad on the Celestial Ridge.", progress = "Were you able to gather the eggs?", completion = "These will work quite nicely, {name}. Thank you for agreeing to help us.\n\nBefore we can continue, however, there is something else we'll need to address.", sourceObjectiveStatus = "unverified-source-field" }
quests[10273] = { id = 10273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troublesome Distractions", description = "Your former employer, Wind Trader Marid, must've gotten wind that you're helping us now. Through my projection, I've seen his nether-stalkers entering the area, hoping to track us down.\n\nWe've been able to evade them so far, but Marid must be dealt with before the problem grows more severe.\n\nIf your impressions of Marid are correct, he'll do just about anything to secure the supply of his product. Return to him and tell him you're prepared to offer a deal. Lure him away and slay him.", sourceObjective = "Speak with Wind Trader Marid and lure him away from his trading post. Deal with him and then return to Tyri and Jorad on the Celestial Ridge.", progress = "This Marid is a fool, or shall I say, was a fool.", completion = "Now that that troublesome ethereal has been dealt with, we can focus our efforts on understanding these nether dragons. I've had a chance to examine the eggs and I've made a few discoveries.", sourceObjectiveStatus = "unverified-source-field" }
quests[10274] = { id = 10274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Celestial Ridge", description = "The nether dragons have the same ferocious temperament as their black dragon forbears, but there is something entirely alien about them. They hatch and mature rapidly, harnessing the strange energies that forged their kind in the destruction of Draenor.\n\nThere is so much more I need to know about them, but I believe the powers may be of use to my own flight. If we can displace the leader of these drakes, Veraku, with a show of dominance, we can cow the rest of them into submission.", sourceObjective = "Use the Challenge of the Blue Flight to provoke Veraku on the southern edge of the Celestial Ridge. Defeat him and return to Tyri and Jorad on the Celestial Ridge.", progress = "Have you challenged and defeated Veraku?", completion = "Well done, {name}. Well done indeed. The nether dragonkin will not accept a blue dragon among them at first, but with time and the firm demonstration of my authority, they will come around. Scattered, isolated, and without a definitive leader, we must be vigilant in preventing them from falling under the sway of a malevolent power, keeping them in check all the while.", sourceObjectiveStatus = "unverified-source-field" }
quests[10275] = { id = 10275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triangulation Point Two", description = "I've recalibrated the triangulation device with the information that you provided from the first point.  You'll use it in exactly the same manner to discover the second.\n\nAll that I can tell you is that the second point is somewhere far to the west.\n\nOnce you've located it, speak with Wind Trader Tuluman; another of the nexus-prince's agents.  He's posing as a weapon merchant at a small trading post next to the bridge, which leads to the island that Manaforge Ara is on.", sourceObjective = "Use the Triangulation Device to point your way toward the second triangulation point. Once you have found it, report the location to Wind Trader Tuluman at Tuluman's Landing, just on the other side of the bridge from the Manaforge Ara island in the Netherstorm.", progress = "You wish to buy or sell?", completion = "Very good indeed.  The nexus-prince shall be pleased!\n\nWe now have the second point, which will now tell us where the third is, and the general vicinity of the crystal!", sourceObjectiveStatus = "unverified-source-field" }
quests[10276] = { id = 10276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Full Triangle", description = "With the data from both the first and second points, I'm now certain that the crystal is at the top of the Ruins of Farahlon to the northeast.\n\nUnfortunately, the data indicates that the crystal is moving, which means that it has already been discovered, probably by the Burning Legion!\n\nJust in case, I recommend that you take some friends along.\n\nSlay the demon that has the crystal and return it to Nexus-Prince Haramad.", sourceObjective = "Recover the Ata'mal Crystal and deliver it to the Image of Nexus-Prince Haramad at the Stormspire in the Netherstorm.", progress = "Hello again, my friend.  How fare your efforts to find the crystal?", completion = "Beyond my wildest dreams, I never thought that you would be able to retrieve the crystal!\n\nAnd then to actually give it to me!  Do you have any idea how powerful it is?\n\nYour selflessness is inspirational and beyond reproach, {name}!  You have given me much to think about.", sourceObjectiveStatus = "unverified-source-field" }
quests[10277] = { id = 10277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Caverns of Time", description = "Greetings, {name}. Please follow the custodian. She will make things a bit more... clear.", sourceObjective = "Andormu at the Caverns of Time has asked that you follow the Custodian of Time around the cavern.", progress = "Do not return until you have at least a rudimentary understanding of what is happening.", completion = "Hopefully you now have a better understanding of what is expected of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10278] = { id = 10278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warp Rifts", description = "Long have I wandered through Outland, searching for the truth of the void.  Now I am old and weak.  Perhaps you will help me? \n\nI must learn the secrets of the voidwalkers.  You must find the Warp Fields to the west.  West of the Expedition Armory there is a dark place on the edge of the abyss where time and space are weak.  Use my unstable warp rift generator in the Warp Fields to create a warp rift.  You must gather warp nether from the creatures that come through.", sourceObjective = "Use the Unstable Warp Rift Generator in the Warp Fields. Gather 3 Warp Nethers from Unstable Voidwalkers and return them to Ogath the Mad in Spinebreaker Post.", progress = "Have you managed to use my experimental device yet?  I think my unstable warp rift generator will work out there so close to the abyss.", completion = "Unbelievable.  You have touched the void itself!  {name}, you have saved my life's work.  But there is more that must be done, and you can help me.", sourceObjectiveStatus = "unverified-source-field" }
quests[10279] = { id = 10279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To The Master's Lair", description = "Ah, {name}. We have been expecting you. Please, allow one of my brothers to fly you down to the master. He awaits you below...", sourceObjective = "Speak to Andormu at the Caverns of Time.", completion = "We must prepare you for the battles that lie ahead...", sourceObjectiveStatus = "unverified-source-field" }
quests[10280] = { id = 10280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Delivery to Shattrath City", description = "I am an ethereal of my word, {name}.  You have truly inspired me.\n\nI am now going to give you the ata'mal crystal to hand over to the naaru.  As it was your heroics that made this possible, I wish for you to deliver it.\n\nYou may use my personal teleporter to go directly to Shattrath City.  Simply step through it and you will be transported there.\n\nGive the crystal to the naaru known as A'dal on the Terrace of Light.  May the trade winds be at your back.", sourceObjective = "Deliver the Ata'mal Crystal to A'dal on the Terrace of Light in Shattrath City.", progress = "<The musical tinkling of the naaru's speech fills your mind.>\n\nI sense that you have something of great power with you, {race}.  What is it that you bring to me?", completion = "You have recovered Spirit's Song!  It is the ata'mal crystal that Prophet Velen left behind with his people for safekeeping before he went upon his ill-fated mission to the Exodar.\n\nOdd that he did not foresee it falling into the hands of the Burning Legion, if even for a short time.\n\nOr, perhaps he did?  It may be that he foresaw all of this, and left it there so that you would retrieve the crystal and deliver it to me here?\n\nI sense that is the truth of it.  You are a great hero of your people, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[10281] = { id = 10281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Formal Introductions", description = "Greetings, {name}. Do not be alarmed. This is merely a projection of my current form. It's the only way my companion and I could keep watch without revealing ourselves.\n\nThe ethereal who approached you, Marid, is little better than a swindler in the guise of a legitimate merchant. I'd like you to consider working with me instead. My purpose out here is to find out more about the unusual dragonkin on this ridge. Meet me at the north end of the ridge and we will discuss this further.", sourceObjective = "Find Tyri at the north end of the Celestial Ridge and speak with her.", completion = "My name is Tyrygosa, of the brood of Malygos, but most call me 'Tyri.' My companion is the paladin Jorad Mace.\n\nWord of these strange dragonkin has already traveled far and I fear that too many will rush to exploit them for profit without realizing the true nature of what they're dealing with. With your help, we're hoping to gain insight into these creatures before others discover their presence.", sourceObjectiveStatus = "unverified-source-field" }
quests[10283] = { id = 10283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taretha's Diversion", description = "Taretha was integral in Thrall's survival and upbringing and instrumental in shaping Thrall's life.\n\nIt was Taretha who created the original diversion at Durnholde, allowing Thrall to escape.\n\nNow the Infinite have captured Taretha and hold her at Tarren Mill. The diversion will not happen without our involvement. You must use the incendiary devices that I give you and burn down the internment lodges in Durnholde. When you have done this, speak with young Thrall in the basement prison of Durnholde.", sourceObjective = "Travel to Durnholde Keep and set 5 incendiary charges at the barrels located inside each of the internment lodges using the Pack of Incendiary Bombs given to you by Erozion.\n\nSpeak to Thrall in the basement prison of Durnholde Keep when you have the Internment Lodges Set Ablaze.", progress = "Who are you?", completion = "You are friends of Taretha? So this is her new plan? Very well then...", sourceObjectiveStatus = "unverified-source-field" }
quests[10284] = { id = 10284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Durnholde", description = "You look upon me now and see only a boy, but in my heart and soul I hide my dreams. I have plans for my people, stranger. One day, they shall overthrow their oppressors and rise as one. They will break free from the bonds that hold them and from that uprising shall be born the orcish Horde.\n\nI promise you, stranger, should we make it out of here alive, when I have the means to reward this selfless deed, I will seek you out... I will find you.\n\n<Thrall nods.>\n\nWe will leave when you are ready.", sourceObjective = "When you are ready to proceed, let Thrall know. Follow Thrall out of Durnholde Keep and help him free Taretha and fulfill his destiny.\n\nSpeak with Erozion in Old Hillsbrad should you complete this task.", progress = "<Erozion nods.>", completion = "You have done a great thing, {name}. Alas, the young warchief's memory of these events must be as they originally were... Andormu awaits you in the master's lair.", sourceObjectiveStatus = "unverified-source-field" }
quests[10285] = { id = 10285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Andormu", description = "This timeline has been restored and the assault of the Infinite Dragonflight upon Hillsbrad has been squashed.\n\nReturn to Andormu at once. He awaits your arrival in the master's lair.", sourceObjective = "Return to the child Andormu at the Caverns of Time in the Tanaris desert.", completion = "Please accept a gift from the bronze flight. These items will assist you in your journeys through time.", sourceObjectiveStatus = "unverified-source-field" }
quests[10286] = { id = 10286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arelion's Secret", description = "Arelion's journal does not deal with any sort of scholarly studies.  It details his escapades with a young female blood elf!  How could I've been such a fool?\n\nUnfortunately, the floozy's identity is not revealed in this journal.  Aledis, a colleague of Arelion's, was his best friend and confidant.  Go question him and find out who he was having this affair with.\n\nI saw Aledis leave Falcon Watch for Zangarmarsh.  Follow the road headed north from town; it'll eventually lead west, toward Zangarmarsh.", sourceObjective = "Magistrix Carinda wants you to interrogate Magister Aledis, last seen traveling from Falcon Watch to Zangarmarsh.", completion = "I'll talk, {class}.  Put your weapon down, I don't want any more trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[10287] = { id = 10287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mistress Revealed", description = "I'm Arelion's friend, but I'm not going to take the beating of my life for him.  His mistress is Viera Sunwhisper.\n\nGo tell that harpy of a wife of his.  What's she going to do anyway?", sourceObjective = "Return to Magistrix Carinda at Falcon Watch in Hellfire Peninsula.", completion = "Viera Sunwhisper?  That lousy little brat.\n\nI will show her I'm not one to be trifled with!", sourceObjectiveStatus = "unverified-source-field" }
quests[10288] = { id = 10288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arrival in Outland", description = "I want you to speak with Amish Wildhammer, standing about 30 paces south of us, and catch the first flight to Honor Hold. When you arrive at Honor Hold, you'll be greeted by Marshal Isildor. I have prepared a report detailing our situation here.  Give him the report, and tell him you're ready for duty.\n\nYou have your orders, soldier, now move out!  And though your blood must be burning to help us against the fiends below, waste no time here.  Honor Hold needs you even more.", sourceObjective = "Commander Duron at the Dark Portal in Hellfire Peninsula wants you to bring Duron's Report to Amish Wildhammer.", progress = "I saw you speaking with Duron over there.  You must be on an important mission!", completion = "Reports for Honor Hold?  No problem -- we'll get you there fast and safe on one of my gryphons!", sourceObjectiveStatus = "unverified-source-field" }
quests[10289] = { id = 10289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to Thrallmar", description = "When you're ready, I'll summon a wyvern to fly you to Thrallmar. Once you arrive, deliver Orion's report to General Krakork.\n\nLok'tar ogar, {name} - good luck.", sourceObjective = "Take Vlagga Freyfeather's Wind Rider to Thrallmar. Bring Orion's Report to General Krakork.", progress = "A report from Orion? Give it here, quickly!\n\n<Frowning, General Krakork quickly scans the tattered document.>\n\nDamn, it's just as we feared. Orion and his warriors could be overrun at any moment!", completion = "I'll rally what troops I can and send them to aid Orion's forces at the Dark Portal. The Legion will not soon forget the battle cry of the Horde! As for you {name}, you've done a great service for Thrallmar this day. I expect you'll be a great help to us here... if you have the wits to survive, that is.", sourceObjectiveStatus = "unverified-source-field" }
quests[10290] = { id = 10290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Farahlite", description = "To the northeast is an area called the Netherstone, a landmark not seen when this was a lush, green land. Newly-exposed crystal formations have shown us a mineral we've called farahlite in honor of this land's former identity.\n\nThe tiny amount of farahlite we've mined has already proven popular with our clients. The highest grade of the mineral comes not from static deposits, but from the giants around the Netherstone. I can offer you a cut of the profits if you'll help supply the higher grade farahlite.", sourceObjective = "Gather 4 pieces of Raw Farahlite and return to Zuben Elgenubi at the Stormspire.", progress = "I understand the dangers of gathering farahlite are great, but so are the opportunities. A merchant who isn't willing to take the risk may as well close his doors and save himself the trouble.", completion = "Ah, yes. This is precisely the grade I was hoping for. We may give up mining the crystal formations altogether if we can secure a supply from the giants.", sourceObjectiveStatus = "unverified-source-field" }
quests[10291] = { id = 10291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Nazgrel", description = "Though our warriors are without peer, our hold on this wasteland is still tenuous. Report to Nazgrel inside the barracks - he has need of agents... such as you. If we can't protect our holdings here, we'll be of no use to anyone. Now go!", sourceObjective = "General Krakork in Thrallmar wants you to speak with Nazgrel.", completion = "We've already lost many brave warriors to this cursed wasteland. I have little interest in sending more untested recruits to the slaughter.\n\n<Nazgrel glares at you sternly through his ragged wolf-mask>\n\nStill, if General Krakork sent you to me, he must have seen something in you. What say you then, {name}? Will you serve your warchief with honor?", sourceObjectiveStatus = "unverified-source-field" }
quests[10292] = { id = 10292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Power!", description = "Gathering a precious commodity in small batches has a quaint, cottage-industry feel to it, but it's just not competitive in today's market.\n\nNo, what we need is a method of mass producing farahlite! Then, the quantity on the market will be completely within our control.\n\nI have an idea, but it's going to require a powerful, focused energy source. There's only one possible place to find an energy source powerful enough. Go to the Legion's camps to our north and 'procure' some of their cannon.", sourceObjective = "Zuben Elgenubi wants you to capture 8 Legion Cannon and bring them back to the Stormspire.", sourceObjectiveStatus = "unverified-source-field" }
quests[10293] = { id = 10293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting the Motherlode", description = "Now that we've got a good baseline product, we're going to need something of higher quality. Certainly the farahlite we've gathered so far is nice, but I know there's better out there.\n\nWe'll have to get a sample directly from Cragskaar, the patriarch of the Farahlon giants! You should be able to find it among the other giants in the Netherstone area. It's got huge pieces of farahlite jutting from its back and that's exactly what we need. Fell the giant and collect a farahlite core from it.", sourceObjective = "Zuben Elgenubi at the Stormspire wants you to obtain a Farahlite Core.", progress = "You're still alive, which means you've either got the core, or you've changed your mind. Which is it?", completion = "Well done! I can't wait to put this to the test.", sourceObjectiveStatus = "unverified-source-field" }
quests[10294] = { id = 10294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Ridge", description = "We have to improve my warp rift generator.  You must take it to Void Ridge.  Head east of here.  You must avoid the foul fort of Zeth'Gor.  To the east beyond Zeth'Gor is a small pass through the mountains.  Through this pass you will find Void Ridge, a terrible place on the edge of the abyss.\n\nYou must kill the walkers that you find there, and bring me shards of their souls.  With their power we will improve upon the warp rift generator and open a portal to the beyond that cannot be closed.", sourceObjective = "Go to Void Ridge and kill the creatures you find. Collect 40 Void Ridge Soul Shards and return them to Ogath the Mad in Spinebreaker Post.", progress = "You have done it then?  You have the shards that we need?", completion = "Excellent, the warp rift generator is almost complete.  There is only one final ingredient we require.  Soon we shall be able to open up a warp rift to the deepest parts of the abyss.  \n\nWho knows what strange creature may come through?  Think of it {name}, the power such knowledge will bring is limitless.", sourceObjectiveStatus = "unverified-source-field" }
quests[10295] = { id = 10295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Abyss", description = "My warp rift generator is complete. You can now use it to summon a true prince of the void, a creature whose soul shard will tell us much of what lies beyond.  \n\nGo south in Void Ridge and use my warp rift generator near the void stones.  Look for a cluster of crystals near the edge of the abyss.  A huge warp rift will form and Void Baron Galaxis will surely appear.  \n\nDestroy this creature and bring me his soul shard.", sourceObjective = "Kill Void Baron Galaxis and collect his soul shard. Take the shard to Ogath the Mad in Spinebreaker Post.", progress = "Have you destroyed Void Baron Galaxis yet?", completion = "You have saved my life's work {name}.  \n\nThey called me insane, they laughed at me, they thought I was mad for my obsession with the Void Ridge and Warp Fields.  Now with this soul shard I can unlock the secrets of the voidwalkers.  I will command the power of the abyss.", sourceObjectiveStatus = "unverified-source-field" }
quests[10296] = { id = 10296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Morass", description = "The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending.\n\nYou must venture through the timeway leading to the Black Morass. Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at.", sourceObjective = "Travel through the Caverns of Time to the Black Morass during the opening of the Dark Portal and speak with Sa'at.", completion = "Indeed, if the orcs never make it to Azeroth, the Alliance will never form. Eventually civil war will break out, further weakening the human kingdoms.\n\nUltimately the Burning Legion will invade Azeroth, destroying it in the absence of any defenders.", sourceObjectiveStatus = "unverified-source-field" }
quests[10297] = { id = 10297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Opening of the Dark Portal", description = "Beyond this timeway the Guardian, Medivh, feverishly works to open the Dark Portal.\n\nScattered across the morass, rifts will materialize. Infinite will pour out of the rifts and attempt to destroy Medivh's shields and, ultimately, Medivh.\n\nKill their rift lords and leaders! Do this until Medivh succeeds.", sourceObjective = "Sa'at inside the Black Morass of the Caverns of Time has tasked you with defending Medivh until he succeeds in opening the Dark Portal.\n\nReturn to Sa'at should you succeed in your task.", progress = "You may only use one chrono-beacon per pocket of time.", completion = "You have done well, {name}. The child, Andormu, wishes to speak to you once more.", sourceObjectiveStatus = "unverified-source-field" }
quests[10298] = { id = 10298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero of the Brood", description = "Return to the child, Andormu, {name}. He awaits you outside this pocket of time, in the master's lair.\n\nI hear flutterings. The Scale of Sands has shown interest in your abilities. Perhaps they too would like to speak with you.", sourceObjective = "Return to the child, Andormu, at the Caverns of Time in the Tanaris desert.", completion = "Once more you have secured the present and the future of this world, {name}. Please accept these items as reward for your accomplishments.", sourceObjectiveStatus = "unverified-source-field" }
quests[10299] = { id = 10299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shutting Down Manaforge B'naar", description = "We cannot shut down the manaforges by force as we'd risk causing an explosion that would shake Outland to the core.\n\nAccording to your transcription, there is an emergency shutdown that permanently disables the technology - a safety mechanism common in naaru constructs.\n\nTo perform this procedure you will have to obtain a crystal that will allow you to communicate with the console.  This access crystal is in the possession of an overseer called Theredis according to our information.", sourceObjective = "Return to Manaforge B'naar and obtain the B'naar Access Crystal from Overseer Theredis. Use it at the Manaforge B'naar console to shut it down and report back to Anchorite Karja.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you succeeded in your task, {name}?", completion = "The Light smiles upon you, {name}.  We were all praying for your success.", sourceObjectiveStatus = "unverified-source-field" }
quests[10300] = { id = 10300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebuilding the Staff", description = "<Ravandwyr inspects the staff, noting that part of the headpiece seems to be missing.>\n\nSimply barbaric! Ekkorash must've taken the staff's crystalline headpiece for use in some other trinket, not realizing that it works in concert with the rest of the staff.\n\nAs long as it remains broken, the staff's power is greatly diminished. With a suitable draenei crystal, I should be able to repair it. I've heard the goblins remarking about the crystals carried by the ghosts at the Enkaat Ruins to the north.", sourceObjective = "Obtain 4 Flawless Crystal Shards from the ghosts at the Enkaat Ruins and return them to Ravandwyr at Area 52.", progress = "Have you managed to find some suitable crystals for a new headpiece for the archmage's staff?", completion = "<Ravandwyr carefully examines the crystals, then selects one.>\n\nThis crystal should work. I'll reshape the stave's socket to secure the new headpiece.\n\nWhen Archmage Vargoth sees it, he will be disappointed, but I can bear my master's disappointment if it means we've freed him.", sourceObjectiveStatus = "unverified-source-field" }
quests[10301] = { id = 10301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking the Compendium", description = "While I'm glad to have most of Krasus's Compendium back, it's useless without the heliotrope oculus. You see, Krasus was well aware of the sheer power of the spells recorded in the book and took steps to safeguard them from prying eyes.\n\nOnly a knowledgeable mage can use the oculus to unlock the compendium's secrets.\n\nDuring Kael'thas's attack, one of his lieutenants, Spellreaver Marathelle, looted it and took it to Sunfury Hold northeast of the tower. No doubt she thought it a pretty little bauble.", sourceObjective = "Obtain the Heliotrope Oculus from Spellreaver Marathelle at Sunfury Hold.", progress = "Have you recovered the oculus?", completion = "Excellent, {name}. Now, we have most of what we'll need to attempt to break Kael'thas's magic.\n\nAnd if the blood elves suffer from the loss of their local commander, so much the better.", sourceObjectiveStatus = "unverified-source-field" }
quests[10302] = { id = 10302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volatile Mutations", description = "The irradiated power cores from the Exodar have been wreaking havoc on the environment here. The most obvious effect has been the appearance of the strange creatures that seem to have sprung up near them.\n\nThere may be something we can do to help them, but now, their sheer numbers are becoming too much for us to handle.\n\nI'd like you to go out and cull their numbers somewhat, and perhaps I'll have another idea after giving it some thought.", sourceObjective = "Kill 8 Volatile Mutations, then return to Botanist Taerix at the Crash Site in Ammen Vale.", progress = "I am working on a solution I think may be effective with the strange creatures. I just need more time.", completion = "You're finished? That's good news. Hopefully, we can find a way to avoid the killing of these mutated beasts in the future.\n\nI believe I have formed a plan that might give us an alternative solution to this problem, but I will need your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[10303] = { id = 10303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood Elves", description = "You must eliminate... the blood elf... threat.  Find out... what they're... up to!\n\nThey're on the... ridge behind me.", sourceObjective = "Kill 10 Blood Elf Scouts then return to Tolaan in the Shadow Ridge of Ammen Vale.", progress = "There are too many of them... We must whittle them down or else the survivors will have no chance against them.", completion = "These blood elves mean to kill us all. How are we to divert them from this course?", sourceObjectiveStatus = "unverified-source-field" }
quests[10304] = { id = 10304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vindicator Aldar", description = "With your help, we were able to find a solution to our problems faster than I could have hoped.\n\nI don't have any other work for you to do. My apprentices and I can handle the rest.\n\nYou should go speak with Vindicator Aldar on the other side of the ship.", sourceObjective = "Speak with Vindicator Aldar at the Crash Site in Ammen Vale.", completion = "{name}, is it? I've heard good things about you and the work you've been doing in the short time since you came to.\n\nWe'll definitely need your help getting things back to normal. Zhanaa, over there, could also use your help, I'm sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[10305] = { id = 10305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abjurist Belmara", description = "This worn, sturdy tome is no spellbook, as you might expect a Kirin Tor mage to carry. The pages of the volume are covered with hand-copied stories, accompanied by colorful illustrations.\n\nThe tome seems to be far older than its former owner and may have even been a family heirloom. A powerful tie to the book may have been the last thread tying Belmara's spirit to the ruins of Kirin'Var. Returning it to its proper place on the bookshelf in her quarters might help appease her restless spirit.", sourceObjective = "Locate Abjurist Belmara's quarters in Wizard Row and return the book to its Bookshelf. Then, speak with Custodian Dieworth at Kirin'Var Village.", progress = "What have you found, {name}?", completion = "Ah, yes. I'd heard that Abjurist Belmara had an old book of stories, but I had no idea that she brought it with her to Outland. I'm certain her spirit will rest easier knowing that you've found it and returned it to her dwelling.", sourceObjectiveStatus = "unverified-source-field" }
quests[10306] = { id = 10306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conjurer Luminrath", description = "The cloak, undoubtedly of high elven craftsmanship, is richly tailored, even by the standards of the Kirin Tor. The symbols and characters sewn into the cloak's fabric hold no meaning for you, but clearly imbue the garment with magical properties.\n\nPerhaps this object binds the spirit of its former owner to this plane of existence. If so, returning it to the dresser in Conjurer Luminrath's quarters might break the spirit's link to this world, allowing it to rest.", sourceObjective = "Locate Conjurer Luminrath's quarters in Wizard Row and return the mantle to his Dresser. Then, speak with Custodian Dieworth at Kirin'Var Village.", progress = "What have you found, {name}?", completion = "We used to always comment that Luminrath would wear that cloak with just about anything. To him, red went equally well with white, black, purple, blue, yellow, orange, and green. He would never wear the same robe two days in a row, but the cloak was always there...", sourceObjectiveStatus = "unverified-source-field" }
quests[10307] = { id = 10307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cohlien Frostweaver", description = "Looking at the hat, you find yourself asking if any Kirin Tor mage would own such headgear. Judging from the hat's wear, it seems the gnome wouldn't go anywhere without it.\n\nYou try on the hat momentarily, discovering no magical properties beyond a faint urge to dance.\n\nThe treasured possession might be the source of the dead mage's bond to the village. Placing the hat in the footlocker in Cohlien's quarters might free his spirit.", sourceObjective = "Locate Cohlien Frostweaver's quarters in Wizard Row and return the hat to his Footlocker. Then, speak with Custodian Dieworth at Kirin'Var Village.", progress = "What have you found, {name}?", completion = "<The custodian smiles at the mention of Cohlien's name.>\n\nYou're absolutely right about the hat. He wore it all the time and wouldn't let it out of his sight.\n\nThere were a couple of times when a fellow mage, who shall remain nameless, 'borrowed' the hat and hid it as a prank. Needless to say the threat of one of Cohlien's frostbolts changed his mind.\n\nI'm going to miss little Cohlien. He had quite a way with the elven women.", sourceObjectiveStatus = "unverified-source-field" }
quests[10308] = { id = 10308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Heap of Ethereals", progress = "The Consortium is keenly interested in wiping out all of the Zaxxis rebels at the Heap to the south.\n\n{class}, if you would like to ingratiate yourself further with us, go back down there and bring back more of their affiliation insignia.", completion = "Traitors, all of them!\n\nGood work, {class}!  If you find your way back down there again, I'm always looking to add to my collection of their insignia!" }
quests[10309] = { id = 10309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Fel Reaver, But with Heart", description = "You see that scrapped fel reaver over there to the south?  Isn't it a thing of beauty?\n\nI want its heart!\n\nWhat?  Yes, of course it has a heart... what doesn't?\n\n<N. D. looks indignant for a moment.>\n\nGo on over there, pry it open, bring back what I want and I'll give you a nice finder's fee in return.\n\nOh, and I'd take a friend or two along if I were you.  These Zaxxis ethereals are a pretty mean bunch!\n\nTake this fel zapper to jumpstart its heart when you're ready to begin.", sourceObjective = "Recover the Heart of the Fel Reaver and deliver it to N. D. Meancamp at The Heap in the Netherstorm.", progress = "My eyesight must be going from all of the nether radiation.  You have that fel reaver's heart yet?", completion = "Wow, look at that... a beating fel reaver heart!  Well, it's not really 'beating', but you know what I mean.\n\nI can't wait to put this thing to good use.  Or, maybe sell it.  I know a few suck... er, clients that might be interested.\n\nHere, you've earned your pay and then some!", sourceObjectiveStatus = "unverified-source-field" }
quests[10310] = { id = 10310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage the Warp-Gate!", description = "With the Burning Legion nearby at the fel reaver scrap field, we must do what we can to stop the flow of demons into the area.\n\nThey have a warp-gate to the south in an area that they've cleverly named Invasion Point: Destroyer.\n\nI need you to go with me to the site and keep me safe while I sabotage it.\n\nAfterward, go to the Midrealm Post to the north inside Eco-Dome Midrealm and apprise Gahruj of our success.\n\nWe're going to need a friend or two of yours along to help with this.", sourceObjective = "Escort Drijya to the warp-gate at Invasion Point: Destroyer, and see to it that he is kept safe while he attempts to sabotage it. Then speak to Gahruj at the Midrealm Post inside Eco-Dome Midrealm in the Netherstorm.", completion = "That is most excellent news, my friend!\n\nYou and Drijya have done us a great service.  With that warp-gate out of commission, the nearby demons will not be getting any further reinforcements.\n\nPlease allow me to reward you in the proper manner of the Consortium.", sourceObjectiveStatus = "unverified-source-field" }
quests[10311] = { id = 10311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drijya Needs Your Help", description = "{class}, it is good to see a helpful face around here.\n\nThe Burning Legion at the nearby fel reaver heap has become more bold, and I am beginning to fear for our safety here.  The demons are constantly receiving reinforcements from Invasion Point: Destroyer to the south.\n\nMy compatriot, Drijya, has gone down there to scout and see if he can do something about the Burning Legion's warp-gate.\n\nPlease find and assist him in any way that you can.", sourceObjective = "Speak with Drijya near Invasion Point: Destroyer in the Netherstorm.", completion = "I hope that Gahruj has sent you to help me with my mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[10312] = { id = 10312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Annals of Kirin'Var", description = "Silencing the spirits has not bled them of their aggression as we had hoped it would. The malevolent spirits you subdued have reemerged in the streets of the town.\n\nWe must uncover what is causing this to happen. The destruction of Kirin'Var was just the beginning, or else the spirits would have been quieted by now.\n\nThe town hall in the southern section of Kirin'Var maintained a logbook of all the residents. Last I heard, it was in the keeping of Battle-Mage Dathric. Perhaps his spirit still has it.", sourceObjective = "Retrieve the Annals of Kirin'Var from the town hall of Kirin'Var Village and return it to Custodian Dieworth.", progress = "Were you able to find the registry?", completion = "<Custodian Dieworth accepts the registry from you, leafing through the pages.>\n\nHmm...\n\nIt seems I was right. There is a pattern here.\n\nThe most aggressive and dangerous ghosts coincide with the most powerful and highest ranking Kirin Tor who resided in the village. The townspeople and tradesmen seem overlooked by comparison. What could this mean?", sourceObjectiveStatus = "unverified-source-field" }
quests[10313] = { id = 10313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Measuring Warp Energies", description = "If our instincts are right and these manaforges have been made using technology from Tempest Keep, then all of Outland could be in grave danger.\n\nTempest Keep's energy-recharging mechanisms were never supposed to be used this close to the land.  The warp energies are capable of destroying this very land, even when contained within Kael's pipelines.\n\nTake this orb to Manaforge B'naar; it is attuned to measure warp energies.  Use it at the pipelines' ends, where they go into the earth.", sourceObjective = "Exarch Orelis in Area 52 wants you to take the Warp-Attuned Orb to Manaforge B'naar and use it at the end of its four pipelines.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you performed the measurements I asked for, {name}?", completion = "This is grave news, {name}.  The warp energies emanating from the pipelines are dangerously high.\n\nWe must find a way to shut down the manaforges or what little remains of Outland will be shattered into pieces.", sourceObjectiveStatus = "unverified-source-field" }
quests[10314] = { id = 10314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lingering Suspicion", description = "The strange magical device resembles nothing you've ever seen before. It's certainly not of blood elf manufacture.\n\nAs you sense spirits moving closer to the building, the orb glows with a greater intensity, which fades as the spirits leave. There's no question that it plays a role in the corruption of the ghosts.\n\nHow it works remains a mystery. Perhaps Custodian Dieworth will have some insight if you can provide the remains of some of the spirits along with your observations.", sourceObjective = "Collect 10 Loathsome Remnants from the twisted spirits in Kirin'Var Village's Chapel Yard and bring them to Custodian Dieworth.", progress = "What have you discovered, {name}?", completion = "<Custodian Dieworth examines the remnants.>\n\nThe device you described sounds like a necromantic focus... I should've known that no-good apprentice would stoop to this. I thought his training would keep him from going this far, but I guess he's proven me wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[10315] = { id = 10315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neutralizing the Nethermancers", description = "The blood elves are fools!  I'm glad that our trade relations with them have fallen apart.  In all of my travels throughout the cosmos, I have never encountered beings so selfish.\n\nThey continue to destroy the land around us with their manaforges, so let's see if we can put a dent in their operations across the bridge at Manaforge Ara.\n\nTheir nethermancers channel energy to and from the blood gems to stabilize the flow of power.  Go over there and wipe them out!", sourceObjective = "Kill 15 Sunfury Nethermancers and return to Nether-Stalker Oazul at Tuluman's Landing in the Netherstorm.", progress = "How many nethermancers have you managed to fell?", completion = "Anything that we can do to encourage them to stop what they're doing at these manaforges is a good thing.\n\nThey certainly do not seem to be able to be reasoned with.  And it seems clear to me that whatever their leaders have in mind, they are insane.\n\nAs remuneration for your faithful service to the goals of the Consortium, I would like to offer you the coin of your realm if it does not offend you.", sourceObjectiveStatus = "unverified-source-field" }
quests[10316] = { id = 10316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching for Evidence", description = "Whoever is behind the transformation of the spirits has been very deliberate in their actions, taking care to target the most powerful mages first, but why? The kind of magic required to influence the spirits of slain Kirin Tor mages must be very powerful.\n\nWhy would a powerful mage go to all this trouble? I'm inclined to say this is another plot of Kael'thas's, designed to cause more misery here. If there are blood elves here, they're likely to be hiding in the houses across the covered bridge.", sourceObjective = "Search Kirin'Var Village's Chapel Yard for clues about who is behind the manipulation of the spirits.", completion = "A glowing orb sits atop a square-shaped pedestal. At first glance, it seems to be a repository for magical energy, but what kind of energy, and for whose use?", sourceObjectiveStatus = "unverified-source-field" }
quests[10317] = { id = 10317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing with the Foreman", description = "The blood elves call the mine underneath Manaforge Ara the Trelleum Mine.  Ever since they lost the one underneath Manaforge Ultris, this is where their sole supply of material for running the forges is coming from.\n\nNeedless to say, it would be a boon for us to cripple their mining operation.  Perhaps we'd even be able to move in and take it over for ourselves?\n\nWhatever the case, I want you to go in there and deal with Foreman Sundown.  The mine is around the back of the island to the left.", sourceObjective = "Deal with Foreman Sundown inside the Trelleum Mine, which is underneath Manaforge Ara in the Netherstorm.", completion = "<The foreman speaks in hushed tones.>\n\nYou came in here to kill me?  Hmph.  Well I guess the ethereal don't know everything, do they?\n\nI'm not the one that you want, trust me.", sourceObjectiveStatus = "unverified-source-field" }
quests[10318] = { id = 10318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing with the Overmaster", description = "I used to be the foreman here.  But now that I've been demoted, I've come to realize our pilgrimage from Quel'Thalas to Outland was all a lie.\n\nA lie perpetrated by Kael'thas to strengthen his forces here in the Netherstorm.\n\nI've tried to convince my brethren that we should leave, especially with the Burning Legion here, but they are all too stubborn.\n\nDo me a favor?  Kill Overmaster Grindgarr.  Then return to your ethereal and tell him that I am no longer his enemy.", sourceObjective = "Slay Overmaster Grindgarr. Then return to Wind Trader Tuluman at Tuluman's Landing in the Netherstorm.", progress = "What news do you bring from Manaforge Ara?  Did you deal with Foreman Sundown?", completion = "A doomguard overmaster?  That's odd!  What's the Burning Legion doing in there?\n\nSo, some of the blood elves are defecting.  We'll keep that in mind if we ever attempt to take the place by force.  At least there's some good news that has come from all of this, no?\n\nPlease, {name}, take this with my deepest gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[10319] = { id = 10319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capturing the Phylactery", description = "I suppose an explanation is in order. You've met one of the archmage's apprentices, Ravandwyr, but there was also another named Naberius.\n\nHe was an ardent student, but was drawn to necromancy. When Kael'thas appeared with his forces, Naberius seized the opportunity to betray the archmage, handing over the secrets to the tower's defense.\n\nNow, it seems, he has become a lich. If we are to stop him, we must capture his phylactery. Knowing him, he would've buried it somewhere out of sight in his domain.", sourceObjective = "Recover Naberius's Phylactery from Kirin'Var Village's Chapel Yard district and bring it to Custodian Dieworth.", progress = "You must recover Naberius's phylactery before we can attack him. Otherwise, he will be invulnerable.", completion = "Excellent work, {name}. Possession of the phylactery will be the key to our victory. When you enter battle with Naberius, I will smash it, exposing him to your attacks.", sourceObjectiveStatus = "unverified-source-field" }
quests[10320] = { id = 10320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy Naberius!", description = "Archmage Vargoth saw the danger in Naberius's pursuit of necromancy, but I don't think he ever anticipated that his own apprentice would wreak this much destruction upon the Kirin Tor.\n\nYou must defeat him, {name}, or else he will continue enslaving the spirits of our fallen brothers, robbing them of their rightful rest and destroying what little remains of Kirin'Var.\n\nWith his phylactery in hand, he can be confronted by two or three combatants, but who knows what his magic might do to more foes?", sourceObjective = "Custodian Dieworth in Kirin'Var Village wants you to confront and defeat Naberius in the village's Chapel Yard.", progress = "Have you destroyed the lich of that wretched Naberius?", completion = "The defeat of Naberius is a great achievement, {name}. I can't help thinking that we might have had a chance against Kael'thas's forces if the apprentice's loyalties had been in the right place that day.", sourceObjectiveStatus = "unverified-source-field" }
quests[10321] = { id = 10321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shutting Down Manaforge Coruu", description = "Your success at B'naar has given us a great deal of hope, {name}.\n\nWe've shared our discoveries with the Scryers and in return they've given us more information on the remaining manaforges.\n\nThree other manaforges still stand, in full control of the Sunfury army.\n\nYou will find Manaforge Coruu to the east.  Overseer Seylanna holds the access crystal there.  Obtain it and use it on the manaforge's control console to begin the emergency shutdown.\n\nWe're all counting on you, {name}.", sourceObjective = "Travel to Manaforge Coruu, east of Area 52, and obtain the Coruu Access Crystal from Overseer Seylanna. Use it at the Manaforge Coruu Console to shut it down and return to Anchorite Karja.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", progress = "Have you completed your task yet, {name}?", completion = "Excellent work.  Only two manaforges remain active.\n\nSoon Kael'thas will be cut off from his main source of power.", sourceObjectiveStatus = "unverified-source-field" }
